// Cyrus eval, bundle mc-coverage: LANE-SELECTION accuracy. Coverage prompts (services/modbuilder/eval/sets/coverage.jsonl)
// carry `expectLanes` from the Minecraft coverage matrix (lib/cyrus/adapters/minecraft-coverage.json). A selector says
// which lanes it would plan for a prompt; this module scores it. The default selector is the deterministic word rules
// the portal already routes with (asset kinds, designer words, data pack rules, worldgen); the live-test planner
// (lib/cyrus/planner on fix/cyrus-live-test-1) plugs in through `selectLanes` once it merges. Pure, no model.
import { detectAssetKinds } from "../assets/plan";
import { matchBossWords, matchDesignerWords, matchGameplayWords, matchHudWords, matchMotionWords } from "../designer/route";
import { matchDataPackRules } from "../datapack/route";
import type { EvalPrompt } from "./set";

/** The planner lane vocabulary (lib/cyrus/planner/lanes.ts LANES) that the coverage matrix uses. "config" is implied by
 * every plugin build, so it is never scored. */
export const SCORED_LANES = ["texture", "itemStates", "sound", "model3d", "creature", "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "datapack", "worldgen", "library"] as const;
export type ScoredLane = (typeof SCORED_LANES)[number];
export type LaneSelector = (p: EvalPrompt) => string[];

/** Today's deterministic rules (what the portal routes on with every switch on). */
export const rulesSelector: LaneSelector = (p) => {
  const t = p.prompt;
  const out = new Set<string>();
  for (const k of detectAssetKinds(t)) out.add(k === "creature" ? "creature" : k);
  if (matchDesignerWords(t).length) out.add("designItem");
  const g = matchGameplayWords(t);
  if (g.menus) out.add("designMenu");
  if (g.quests) out.add("designQuest");
  if (matchBossWords(t).length) out.add("designBoss");
  if (matchHudWords(t).hud) out.add("designHud");
  if (matchMotionWords(t).length) out.add("motion");
  const dp = matchDataPackRules(t, "minecraft", { worldgen: true });
  if (dp.some((x) => x !== "worldgen")) out.add("datapack");
  if (dp.includes("worldgen")) { out.add("worldgen"); out.add("datapack"); }
  return [...out];
};

export type LaneScore = { key: string; expected: string[]; selected: string[]; missed: string[]; extra: string[]; exact: boolean };

export function scoreLanes(p: EvalPrompt, selected: string[]): LaneScore | null {
  if (!p.expectLanes) return null;
  const want = new Set(p.expectLanes.filter((l) => (SCORED_LANES as readonly string[]).includes(l)));
  const got = new Set(selected.filter((l) => (SCORED_LANES as readonly string[]).includes(l)));
  const missed = [...want].filter((l) => !got.has(l)).sort();
  const extra = [...got].filter((l) => !want.has(l)).sort();
  return { key: p.key, expected: [...want].sort(), selected: [...got].sort(), missed, extra, exact: !missed.length && !extra.length };
}

export type LaneAccuracy = {
  selector: string; prompts: number; exact: number; exactPct: number | null;
  /** micro-averaged over every (prompt, lane) pair. */
  precisionPct: number | null; recallPct: number | null;
  perLane: Record<string, { expected: number; selected: number; hit: number }>;
  misses: LaneScore[];
};

const pct = (a: number, b: number) => (b ? Math.round((a / b) * 1000) / 10 : null);

export function laneAccuracy(prompts: EvalPrompt[], select: LaneSelector = rulesSelector, name = "rules"): LaneAccuracy {
  const scores = prompts.map((p) => scoreLanes(p, select(p))).filter((x): x is LaneScore => !!x);
  const perLane: LaneAccuracy["perLane"] = {};
  let tp = 0, fp = 0, fn = 0;
  for (const s of scores) {
    for (const l of new Set([...s.expected, ...s.selected])) {
      const r = (perLane[l] ??= { expected: 0, selected: 0, hit: 0 });
      if (s.expected.includes(l)) r.expected++;
      if (s.selected.includes(l)) r.selected++;
      if (s.expected.includes(l) && s.selected.includes(l)) { r.hit++; tp++; }
    }
    fp += s.extra.length; fn += s.missed.length;
  }
  const exact = scores.filter((s) => s.exact).length;
  return { selector: name, prompts: scores.length, exact, exactPct: pct(exact, scores.length), precisionPct: pct(tp, tp + fp), recallPct: pct(tp, tp + fn), perLane: Object.fromEntries(Object.entries(perLane).sort()), misses: scores.filter((s) => !s.exact) };
}

export function laneAccuracyMarkdown(a: LaneAccuracy): string {
  return [
    `## Lane selection (${a.selector})`, "",
    `${a.prompts} prompts with expected lanes: exact ${a.exact} (${a.exactPct ?? "-"}%), precision ${a.precisionPct ?? "-"}%, recall ${a.recallPct ?? "-"}% (config is implied by every plugin and not scored).`, "",
    "| lane | expected | selected | hit |", "|---|---|---|---|",
