"use strict";
// Dependency-free Java structure reader (Cyrus structure round, 2026-10-14). Not a full parser: a lexer that is exact for comments,
// string / char / text-block literals, plus bracket matching, a statement splitter and a type-outline reader. That is enough for
// the three jobs that used to rely on line regexes:
//   astperf.js       spawn / drop / summon inside loops, forEach / stream lambdas and fast scheduler timers (+ a verified rewrite)
//   workspacemap.js  a compact outline of an existing project for change builds
//   memberindex.js   token-aware symbol replacement for "did you mean" fixes
// Every function returns null / ok:false on input it cannot read (unbalanced brackets, unterminated literal): callers then keep
// their old behaviour. tree-sitter was evaluated and not used: the native addon would be a new build-time dependency of the image
// and every question asked here is answered by token structure (see agent-notes CE-structure-2026-10-14.md).

const OPEN = { "(": ")", "[": "]", "{": "}" };
const CLOSE = new Set([")", "]", "}"]);

/** Tokens: {t: id|num|str|chr|op, v, s, e, line}. Comments and whitespace are dropped (offsets s/e point into src). */
function lex(src) {
  const toks = [];
  const n = src.length;
  let i = 0, line = 1;
  const push = (t, s, e) => toks.push({ t, v: src.slice(s, e), s, e, line });
  while (i < n) {
    const c = src[i];
    if (c === "\n") { line++; i++; continue; }
    if (c === " " || c === "\t" || c === "\r" || c === "\f") { i++; continue; }
    if (c === "/" && src[i + 1] === "/") { while (i < n && src[i] !== "\n") i++; continue; }
    if (c === "/" && src[i + 1] === "*") {
      const e = src.indexOf("*/", i + 2);
      if (e < 0) return { src, toks, ok: false };
      for (let j = i; j < e; j++) if (src[j] === "\n") line++;
      i = e + 2; continue;
    }
    if (c === '"') {
      if (src.startsWith('"""', i)) {
        let j = i + 3;
        for (; j < n; j++) { if (src[j] === "\\") { j++; continue; } if (src.startsWith('"""', j)) break; }
        if (j >= n) return { src, toks, ok: false };
