      }
      m = e + 1;
    }
    return { type, next: close + 1 };
  };
  parseTypes(0, k.length, types);
  return { package: pkg, imports, types, lines: src.split("\n").length };
}

module.exports = { lex, index, parse, stmtEnd, splitStatements, blockKind, callArgs, receiverStart, outline, text, isId, isOp, OPEN, MODS };

