"use strict";
// Structural perf rules (Cyrus structure round, card 4; MB_AST_PERF=1, default OFF).
//
// The line-regex rule `perf-spawn-in-loop` (perf.js) and the autofix behind it (autofix.fixPerf) understand one shape: a plain
// `x.spawn(...);` line inside a braced for/while. Everything else fell through to a model repair (6-7 of ~21 repairs per eval,
// 11 hits in first1..fourth1). This module reads the file's token structure (javaast.js, no dependencies) and
//
//   detect(src)   finds spawn / spawnEntity / spawnFallingBlock / dropItem / dropItemNaturally / summon (and a `summon` command
//                 through dispatchCommand) that run repeatedly and are not bounded by NxPerf:
//                   for / enhanced for / while / do-while, braced or braceless, nested;
//                   forEach / forEachOrdered / peek / map / flatMap / removeIf / replaceAll / generate / iterate lambdas and
//                   anonymous classes, stream pipelines;
//                   bodies of scheduler timers (runTaskTimer, scheduleSyncRepeatingTask, runAtFixedRate, new BukkitRunnable(){}
//                   .runTaskTimer, NxPerf.timer) whose literal period is 10 ticks or less.
//                 A call is bounded when it sits inside `if (NxPerf.spawnAllowed|take|rate|remaining|grant(...))`, after a
//                 `if (!NxPerf.spawnAllowed(...)) return|continue|break|throw;` in the same block, in a loop whose header takes
//                 from NxPerf, or in the worker of NxPerf.queue(...). (The old rule skipped a WHOLE file as soon as any call
//                 was guarded anywhere.)
//   rewrite(src)  wraps each finding in `if (NxPerf.spawnAllowed("<class>-<method>", <chunk>)) { <statement> }`, the existing
//                 NxPerf API, behaviour otherwise unchanged. Compile safety is by construction and then checked:
//                   - a braceless loop / if body gets braces first; an expression lambda body of a known void callee becomes a block;
//                   - a declaration whose variable is used later wraps the rest of its block (never `continue`, never null);
//                   - declined (left to the model, reported in `skipped`): the call is in a loop/if condition, a return value, a
//                     switch case group, a value lambda (map/computeIfAbsent), an assignment to a blank variable, a block
//                     whose tail would swallow a value `return`;
//                   - the chunk argument is evaluated again only when it is a pure getter chain; anything else passes null;
//                   - the result must re-lex with balanced brackets and have fewer findings than the input, else it is dropped.

const J = require("./javaast");

const enabled = (env = process.env) => /^(1|true|on|yes)$/i.test(String(env.MB_AST_PERF ?? "").trim());

const SPAWN_NAMES = new Set(["spawn", "spawnEntity", "spawnFallingBlock", "dropItem", "dropItemNaturally", "summon"]);
const LOOP_CALLS = new Set(["forEach", "forEachOrdered", "forEachRemaining", "peek", "map", "flatMap", "mapToObj", "mapToInt", "generate", "iterate", "removeIf", "replaceAll"]);
const TIMER_CALLS = new Set(["runTaskTimer", "runTaskTimerAsynchronously", "scheduleSyncRepeatingTask", "scheduleAsyncRepeatingTask", "runAtFixedRate", "scheduleAtFixedRate"]);
// callees whose lambda argument is a void-compatible Consumer / Runnable: an expression body may become a block
const VOID_LAMBDA_CALLS = new Set(["forEach", "forEachOrdered", "forEachRemaining", "peek", "ifPresent", "ifPresentOrElse", "runTask", "runTaskLater", "runTaskAsynchronously",
  "runTaskLaterAsynchronously", "runTaskTimer", "runTaskTimerAsynchronously", "scheduleSyncDelayedTask", "scheduleSyncRepeatingTask", "timer", "queue", "execute", "run"]);
const BOUND = new Set(["spawnAllowed", "take", "rate", "remaining", "grant"]);
const FAST_PERIOD_TICKS = 10;
const JUMPS = new Set(["return", "continue", "break", "throw"]);
const CONTROL_HEADERS = new Set(["if", "for", "while", "switch", "catch", "synchronized", "try"]);
const SUMMON_CMD = /^["']\/?(?:execute\b.*\brun\s+)?summon\b/;
const PURE_GETTER = /^(get\w*|clone|toLocation|toBlockLocation)$/;

const kindOf = (name) => (/^drop/.test(name) ? "drop" : name === "summon" ? "summon" : "spawn");

function rangeHasBound(T, a, b) {
  const k = T.toks;
  for (let i = a; i <= b && i < k.length; i++) {
    if (k[i].t === "id" && k[i].v === "NxPerf" && J.isOp(T, i + 1, ".") && k[i + 2] && BOUND.has(k[i + 2].v)) return { at: i, negated: J.isOp(T, i - 1, "!") };
  }
  return null;
}

/** The regions (token ranges) in which a call runs repeatedly, and the regions NxPerf already bounds. */
function regionsOf(T) {
  const k = T.toks;
  const repeat = []; // {kind, a, b, period?}
  const guarded = []; // [a, b]
  const doWhile = new Set();
  for (let i = 0; i < k.length; i++) {
    const t = k[i];
    if (t.t !== "id") continue;
    const afterDot = i > 0 && J.isOp(T, i - 1, ".");
    if ((t.v === "for" || t.v === "while") && !afterDot && J.isOp(T, i + 1, "(")) {
      if (doWhile.has(i)) continue;
      const close = T.match[i + 1];
      const a = close + 1;
      const b = J.stmtEnd(T, a);
      repeat.push({ kind: t.v, a, b });
      if (rangeHasBound(T, i + 1, close)) guarded.push([a, b]);
