    if (!name) continue;
    const ctx = [];
    for (const r of repeat) {
      if (i <= r.a || i >= r.b + 0) { if (!(i > r.a && i <= r.b)) continue; }
      if (r.kind === "timer" && !(r.period !== null && r.period !== undefined && r.period <= FAST_PERIOD_TICKS)) continue;
      ctx.push(r.kind);
    }
    if (!ctx.length) continue;
    if (guarded.some(([a, b]) => i >= a && i <= b)) continue;
    findings.push({ ci: i, line: t.line, name, kind, ctx: [...new Set(ctx)] });
  }
  return { ok: true, findings, T };
}

// ----------------------------------------------------------------------------------------------- rewrite
const IDENT = /^[A-Za-z_$][\w$]*$/;
const keyPart = (s) => String(s || "").replace(/[^A-Za-z0-9_-]/g, "-");

/** `<first arg>.getChunk()` when the first argument is a side-effect free getter chain, else `null`. */
function chunkExpr(T, ci) {
  const args = J.callArgs(T, ci + 1);
  if (!args.length) return "null";
  const a = args[0];
  const k = T.toks;
  if (a.s > a.e) return "null";
  let j = a.s;
  if (!(k[j].t === "id" && k[j].v !== "new")) return "null";
  j++;
  while (j <= a.e) {
    if (!J.isOp(T, j, ".") || !k[j + 1] || k[j + 1].t !== "id") return "null";
    const name = k[j + 1].v;
    j += 2;
    if (j <= a.e && J.isOp(T, j, "(")) {
      if (T.match[j] !== j + 1 || !PURE_GETTER.test(name)) return "null";
      j += 2;
    }
  }
  return `${J.text(T, a.s, a.e)}.getChunk()`;
}

function methodNameAt(T, i) {
  let p = T.parent[i];
  while (p >= 0) {
    if (J.isOp(T, p, "{") && J.blockKind(T, p) === "method") {
      const o = T.match[p - 1];
      return o > 0 && T.toks[o - 1].t === "id" ? T.toks[o - 1].v : null;
    }
    p = T.parent[p];
  }
  return null;
}

/** Plan one wrap. Returns { edits: [[offset, text]...], desc } or { skip: reason }. */
function plan(T, f, cls) {
  const k = T.toks;
  const ci = f.ci;
  const key = `${keyPart(cls).toLowerCase()}-${keyPart(methodNameAt(T, ci) || f.name)}`.slice(0, 48);
  const guard = `if (NxPerf.spawnAllowed("${key}", ${f.kind === "summon" && f.name === "summon" && !J.isOp(T, ci - 1, ".") ? "null" : chunkExpr(T, ci)}))`;
  // 1. climb to the nearest block, or to an expression lambda argument on the way
  let p = T.parent[ci];
  let block = -1;
  while (p >= 0) {
    const v = k[p].v;
    if (v === "(") {
      const b = p - 1;
      if (b >= 0 && k[b].t === "id" && CONTROL_HEADERS.has(k[b].v)) return { skip: "the call is in a condition or loop header" };
      const args = J.callArgs(T, p);
      const arg = args.find((a) => a.s <= ci && ci <= a.e);
      if (arg) {
        let arrow = -1;
        for (let j = arg.s; j <= arg.e; j++) {
          if (k[j].t === "op" && J.OPEN[k[j].v]) { j = T.match[j]; continue; }
          if (k[j].t === "op" && k[j].v === "->") { arrow = j; break; }
        }
        if (arrow >= 0 && ci > arrow) {
          const callee = k[p - 1] && k[p - 1].t === "id" ? k[p - 1].v : "";
          if (!VOID_LAMBDA_CALLS.has(callee)) return { skip: `a value lambda (${callee || "?"}): the guard would change what it returns` };
          const bs = arrow + 1, be = arg.e;
          for (let j = bs; j <= be; j++) {
            if (k[j].t === "op" && J.OPEN[k[j].v]) { j = T.match[j]; continue; }
            if (k[j].t === "op" && /^(\?|\+|-|\*|\/|%|&&|\|\||==|!=|<|>|&|\||\^)$/.test(k[j].v) && !(k[j].v === "-" && false)) return { skip: "lambda body is not a single call" };
          }
          if (k[be].v !== ")") return { skip: "lambda body is not a call" };
          return { edits: [[k[bs].s, `{ ${guard} { `], [k[be].e, "; } }"]], desc: `${guard} (lambda body)` };
        }
      }
    } else if (v === "{") {
      const bk = J.blockKind(T, p);
      if (bk === "array" || bk === "class" || bk === "anon") return { skip: "a field initializer" };
      block = p;
      break;
    }
    p = T.parent[p];
  }
  if (block < 0) return { skip: "no enclosing block" };
  const bkind = J.blockKind(T, block);
  const isSwitch = bkind === "control:switch";
  const stmts = J.splitStatements(T, block, isSwitch);
  let S = stmts.find((s) => s.s <= ci && ci <= s.e);
  if (!S) return { skip: "statement not found" };
  // 2. descend through braceless control bodies
  let braceless = false;
  for (let guardN = 0; guardN < 8; guardN++) {
    const first = k[S.s];
    if (first.t !== "id") break;
    if (first.v === "if" && J.isOp(T, S.s + 1, "(")) {
      const hc = T.match[S.s + 1];
      if (ci <= hc) return { skip: "the call is in a condition" };
      const thenEnd = J.stmtEnd(T, hc + 1);
      if (ci <= thenEnd) S = { s: hc + 1, e: thenEnd };
      else S = { s: thenEnd + 2, e: S.e };
      braceless = true; continue;
    }
    if ((first.v === "for" || first.v === "while" || first.v === "synchronized") && J.isOp(T, S.s + 1, "(")) {
      const hc = T.match[S.s + 1];
      if (ci <= hc) return { skip: "the call is in a loop header" };
      S = { s: hc + 1, e: S.e }; braceless = true; continue;
    }
    if (first.v === "do") {
      const be = J.stmtEnd(T, S.s + 1);
      if (ci > be) return { skip: "the call is in a loop condition" };
      S = { s: S.s + 1, e: be }; braceless = true; continue;
    }
    if (["try", "switch", "return", "throw", "yield", "break", "continue", "case", "default", "class", "interface", "enum", "record", "else"].includes(first.v)) {
      return { skip: `the call is in a ${first.v} statement` };
    }
    break;
  }
  if (!J.isOp(T, S.e, ";")) return { skip: "statement does not end with ';'" };
  // lambda defined at statement level: the guard must sit inside it, not around its creation
  for (let j = S.s; j < ci; j++) {
    if (k[j].t === "op" && J.OPEN[k[j].v]) { if (T.match[j] > ci) break; j = T.match[j]; continue; }
    if (k[j].t === "op" && k[j].v === "->") return { skip: "a lambda assigned or passed outside a call argument list" };
  }
  // 3. declaration / assignment analysis
  let eq = -1;
  for (let j = S.s; j < S.e; j++) {
    if (k[j].t === "op" && J.OPEN[k[j].v]) { j = T.match[j]; continue; }
    if (k[j].t === "op" && k[j].v === ",") return { skip: "multiple declarators" };
    if (k[j].t === "op" && k[j].v === "=" && eq < 0) eq = j;
  }
  let tail = false;
  if (eq > S.s) {
    const nameTok = k[eq - 1];
    const prev = k[eq - 2];
    const isDecl = nameTok.t === "id" && eq - 1 > S.s && prev && ((prev.t === "id" && !["return", "throw", "new"].includes(prev.v)) || (prev.t === "op" && (prev.v === ">" || prev.v === "]")));
    if (isDecl) {
      const used = (() => {
        const lastStmt = stmts[stmts.length - 1];
        for (let j = S.e + 1; j <= lastStmt.e; j++) if (k[j].t === "id" && k[j].v === nameTok.v) return true;
        return false;
      })();
      if (used) {
        if (braceless || isSwitch) return { skip: "the variable is used after the statement and the block cannot be wrapped" };
        const lastStmt = stmts[stmts.length - 1];
        for (let j = S.e + 1; j <= lastStmt.e; j++) {
          if (k[j].t === "id" && k[j].v === "return" && !J.isOp(T, j + 1, ";")) return { skip: "the rest of the block returns a value" };
        }
        tail = lastStmt;
      }
    } else if (eq === S.s + 1 && nameTok.t === "id" && IDENT.test(nameTok.v)) {
      const blank = new RegExp(`(^|[;{}(,\\s])[A-Za-z_][\\w<>\\[\\],.? ]*\\s+${nameTok.v}\\s*;`).test(T.src);
      if (blank) return { skip: "assignment to a variable that has no other initializer" };
    }
  }
  if (tail) return { edits: [[k[S.s].s, `${guard} { `], [k[tail.e].e, " }"]], desc: `${guard} (rest of block)` };
  const open = braceless ? `{ ${guard} { ` : `${guard} { `;
  const close = braceless ? " } }" : " }";
  return { edits: [[k[S.s].s, open], [k[S.e].e, close]], desc: guard };
}

function applyEdits(src, edits) {
  const sorted = edits.slice().sort((a, b) => b[0] - a[0]);
  let out = src;
  for (const [off, txt] of sorted) out = out.slice(0, off) + txt + out.slice(off);
  return out;
}

/**
 * Wrap every rewritable finding. Returns { text, fixes: [{line, kind, from, to, via, ctx}], skipped: [{line, name, ctx, reason}] }.
 * text === src when nothing could be changed. cls = simple class name (used in the budget key).
 */
function rewrite(src, cls = "mod") {
  let text = src;
  const fixes = [];
  const skippedAt = new Map();
  for (let round = 0; round < 40; round++) {
    const d = detect(text);
    if (!d.ok) break;
    const todo = d.findings.filter((f) => !skippedAt.has(`${f.line}|${f.name}`));
    if (!todo.length) break;
    const f = todo[0];
    const p = plan(d.T, f, cls);
    if (p.skip) { skippedAt.set(`${f.line}|${f.name}`, { line: f.line, name: f.name, ctx: f.ctx, reason: p.skip }); continue; }
    const next = applyEdits(text, p.edits);
    const d2 = detect(next);
    if (!d2.ok || d2.findings.length >= d.findings.length) { skippedAt.set(`${f.line}|${f.name}`, { line: f.line, name: f.name, ctx: f.ctx, reason: "the rewrite did not bound the call" }); continue; }
    const t = d.T.toks;
    const stmtFrom = text.slice(t[Math.max(0, f.ci - 6)].s, t[Math.min(t.length - 1, d.T.match[f.ci + 1] + 1)].e).replace(/\s+/g, " ").trim().slice(0, 160);
    fixes.push({ line: f.line, kind: "perf-spawn-guard", from: stmtFrom, to: p.desc.slice(0, 160), via: "ast", ctx: f.ctx });
    text = next;
  }
  // what is still unbounded (reported, left to the model)
  const left = detect(text);
  const skipped = left.ok ? left.findings.map((f) => skippedAt.get(`${f.line}|${f.name}`) || { line: f.line, name: f.name, ctx: f.ctx, reason: "not rewritten" }) : [];
  return { text, fixes, skipped };
}

module.exports = { enabled, detect, rewrite, plan, regionsOf, SPAWN_NAMES, FAST_PERIOD_TICKS };

