/**
 * deps: { classIndex(v) -> Map(simple -> [fqn]), getClass?(v, fqn) -> rec|null, packageClasses?(v, pkg) -> [fqn] }
 * Returns { fixes: [{file, line, kind, from, to}] }; files are rewritten in place. Only exact, unambiguous edits.
