    for (const t of hits.reverse()) out = out.slice(0, t.s) + to + out.slice(t.e);
    if (hits.length) { e.src = out; e.dirty = true; }
    return hits.length;
  };

  const seen = new Set();
  for (const b of parseBlocks(javacOut)) {
    const e = load(b.file);
    if (!e) continue;
    const key = `${b.file}|${b.line}|${b.kind}|${b.name}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const lineText = e.src.split("\n")[b.line - 1] || "";
    if (b.kind === "class") {
      const imp = /^\s*import\s+([\w.]+)\.(\w+)\s*;\s*$/.exec(lineText);
      let pkg = null;
      if (imp && imp[2] === b.name) pkg = imp[1];
      else {
        const lp = /^package\s+([\w.]+)/.exec(b.location);
        if (lp && imp) pkg = lp[1];
      }
      if (!pkg) continue;
      if (!API_PKG.test(`${pkg}.`)) continue;
      const pool = pkgClasses(v, pkg).map((f) => f.slice(f.lastIndexOf(".") + 1));
      if (!pool.length || pool.includes(b.name)) continue;
      const p = pick(b.name, pool);
      if (!p) continue;
      // never collide with something the file already declares or imports under that name
      if (new RegExp(`\\b(class|interface|enum|record)\\s+${p.name}\\b`).test(e.src)) continue;
      if (new RegExp(`^\\s*import\\s+[\\w.]+\\.${p.name}\\s*;`, "m").test(e.src)) continue;
      const n = renameTokens(e, b.name, p.name);
      if (n) fixes.push({ file: b.file, line: b.line, kind: "did-you-mean-class", from: `${pkg}.${b.name}`, to: `${pkg}.${p.name}` });
      continue;
    }
    const fqn = locationType(b.location, e.src, v, deps);
    if (!fqn) continue;
    const pool = memberPool(v, fqn, b.kind, get, b.argc);
    if (!pool || !pool.names.length) continue;
    if (pool.names.includes(b.name)) continue; // exists with another arity: a real bug for the model
    const p = pick(b.name, pool.names);
    if (!p) continue;
    // same-name constant on a different type is not what javac asked about; the edit is the one identifier at the caret
    if (replaceAt(e, b.line, b.col, b.name, p.name)) {
      fixes.push({ file: b.file, line: b.line, kind: b.kind === "method" ? "did-you-mean-method" : "did-you-mean-member", from: `${simple(fqn)}.${b.name}`, to: `${simple(fqn)}.${p.name}` });
    }
  }
  for (const [, e] of files) if (e.dirty) fs.writeFileSync(e.abs, e.src);
  return { fixes };
}

// ------------------------------------------------------------------------------------------------- hints
/**
 * The relevant members of ONE type for a missing member / method, as one line for the repair prompt. null when the type is
 * unknown. kind: variable | method. At most `max` names, ranked by shared words with the wanted name, then edit distance.
 */
function hint(v, fqn, kind, name, argc = null, opts = {}) {
  const get = opts.getClass || ((vv, f) => getClass(vv, f));
  const pool = memberPool(v, fqn, kind, get, null);
  if (!pool || !pool.names.length) return null;
  const max = opts.max || 12;
  const ww = new Set(words(name));
  const wf = flat(name);
  const exactArity = kind === "method" && argc !== null ? new Set(memberPool(v, fqn, kind, get, argc).names) : null;
  const ranked = pool.names
    .map((n) => {
      const nw = words(n);
      const shared = nw.filter((w) => ww.has(w)).length;
      return { n, shared, d: lev(wf, flat(n)), ar: exactArity ? (exactArity.has(n) ? 0 : 1) : 0 };
    })
    .sort((a, b) => b.shared - a.shared || a.ar - b.ar || a.d - b.d || a.n.localeCompare(b.n));
  const top = ranked.filter((x) => x.shared > 0 || x.d <= Math.max(3, Math.floor(wf.length / 3))).slice(0, max);
  const list = (top.length ? top : ranked.slice(0, Math.min(max, 8))).map((x) => x.n);
  const s = simple(fqn);
  const total = pool.names.length;
  if (kind === "variable") return `- ${s} has no ${name} in Paper ${v} (it has ${total} fields/constants). The closest real ones: ${list.join(", ")}.${total > list.length ? " Pick one of these or use a different type." : ""}`;
  return `- ${s}.${name}(${argc === null ? "..." : `${argc} arg${argc === 1 ? "" : "s"}`}) does not exist in Paper ${v}. The closest real methods: ${list.join(", ")}.`;
}

module.exports = { enabled, parseJavap, getClass, fromRecords, packageClasses, loadFile, lev, pick, memberPool, parseBlocks, fixMembers, hint, ancestry, words };

