    if (!name || /^\d/.test(name)) continue;
    const mods = new Set(["public", "protected", "static", "final", "abstract", "default", "synchronized", "native", "strictfp"]);
    const ret = parts.filter((x) => !mods.has(x)).join(" ");
    if (!ret) continue; // constructor
    if (name.includes(".")) continue;
    rec.m.push([name, params.length, simple(ret), params.map(simple).join(",")]);
  }
  rec.f = [...new Set(rec.f)];
  rec.c = [...new Set(rec.c)];
  return { fqn, rec };
}

// ------------------------------------------------------------------------------------------------ loading
const fileCache = new Map(); // v -> {classes} | null
const classCache = new Map(); // `${v}|${fqn}` -> rec | null

function loadFile(v, dir = CP_DIR) {
  const k = `${dir}|${v}`;
  if (fileCache.has(k)) return fileCache.get(k);
  let data = null;
  try { data = JSON.parse(fs.readFileSync(path.join(dir, `${v}.members.json`), "utf8")); } catch { data = null; }
  fileCache.set(k, data);
  return data;
}

/** The index record of one class (from <v>.members.json, else javap on demand), or null. */
function getClass(v, fqn, opts = {}) {
  const dir = opts.dir || CP_DIR;
  const f = loadFile(v, dir);
  if (f && f.classes[fqn]) return f.classes[fqn];
  const k = `${dir}|${v}|${fqn}`;
  if (classCache.has(k)) return classCache.get(k);
  let rec = null;
  if (!f || opts.javap) {
    try {
      const cp = fs.readFileSync(path.join(dir, `${v}.txt`), "utf8").trim();
      const out = execFileSync("javap", ["-public", "-cp", cp, fqn], { encoding: "utf8", timeout: 30000, maxBuffer: 16 * 1024 * 1024, env: { PATH: process.env.PATH, JAVA_HOME: process.env.JAVA_HOME } });
      const p = parseJavap(out);
      rec = p ? p.rec : null;
    } catch { rec = null; }
  }
  classCache.set(k, rec);
  return rec;
}

/** Test seam: install records without any file or javap. */
function fromRecords(records) {
  return { getClass: (_v, fqn) => records[fqn] || null, packageOf: (_v, pkg) => Object.keys(records).filter((f) => f.slice(0, f.lastIndexOf(".")) === pkg) };
}

function packageClasses(v, pkg, opts = {}) {
  const f = loadFile(v, opts.dir || CP_DIR);
  if (f) return Object.keys(f.classes).filter((x) => x.slice(0, x.lastIndexOf(".")) === pkg && !x.includes("$"));
  const idx = opts.classIndex ? opts.classIndex(v) : null;
  if (!idx) return [];
  const out = [];
  for (const fqns of idx.values()) for (const x of fqns) if (x.slice(0, x.lastIndexOf(".")) === pkg) out.push(x);
  return out;
}

// -------------------------------------------------------------------------------------------- distance + pick
function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}
const words = (s) => String(s).replace(/([a-z0-9])([A-Z])/g, "$1_$2").toUpperCase().split(/[_\s]+/).filter(Boolean);
const flat = (s) => String(s).toUpperCase().replace(/_/g, "");

/**
 * The single best candidate for `want`, or null when it is not unambiguous.
 * Rules (all must hold): edit distance on the flattened upper-case names <= max(1, min(3, floor(len / 5))) ... with a floor
 * of 2 for names of 8+ chars; the runner-up is at least 2 edits further away; OR the wanted name has 2+ words and exactly
 * one candidate contains all of them in order.
 */
function pick(want, pool) {
  const wf = flat(want);
  const scored = pool.filter((c) => c !== want).map((c) => ({ c, d: lev(wf, flat(c)) })).sort((a, b) => a.d - b.d || a.c.length - b.c.length);
  const limit = wf.length >= 14 ? 4 : wf.length >= 8 ? 3 : wf.length >= 5 ? 2 : 1;
  if (scored.length && scored[0].d <= limit && (scored.length === 1 || scored[1].d - scored[0].d >= 2)) return { name: scored[0].c, d: scored[0].d, by: "edit" };
  const ww = words(want);
  if (ww.length >= 2) {
    const hit = pool.filter((c) => {
      const cw = words(c); let at = 0;
      for (const w of ww) { const j = cw.indexOf(w, at); if (j < 0) return false; at = j + 1; }
      return c !== want;
    });
    if (hit.length === 1) return { name: hit[0], d: lev(wf, flat(hit[0])), by: "words" };
  }
  return null;
}

/** supertypes, nearest first (cycle safe, API types only). */
function ancestry(v, fqn, get) {
  const seen = new Set([fqn]);
  const out = [];
  const q = [fqn];
  while (q.length && out.length < 40) {
    const cur = q.shift();
    const rec = get(v, cur);
    if (!rec) continue;
    for (const s of rec.s || []) if (!seen.has(s)) { seen.add(s); out.push(s); q.push(s); }
  }
  return out;
}

function memberPool(v, fqn, kind, get, argc) {
  const own = get(v, fqn);
  if (!own) return null;
  const all = [fqn, ...ancestry(v, fqn, get)];
  const names = new Set();
  for (const t of all) {
    const r = t === fqn ? own : get(v, t);
    if (!r) continue;
    if (kind === "variable") { for (const x of r.f) names.add(x); for (const x of r.c) names.add(x); }
    else for (const [n, a] of r.m) if (!NO_METHODS.test(n) && (argc === null || a === argc)) names.add(n);
  }
  return { names: [...names], own };
}

// --------------------------------------------------------------------------------------------- javac parsing
const BLOCK = /^([^\s:]+\.java):(\d+): error: cannot find symbol\n([^\n]*)\n([^\n]*)\^[^\n]*\n\s+symbol:\s+(variable|method|class)\s+([\w$]+)(?:\(([^)]*)\))?(?:\n\s+location:\s+([^\n]+))?/gm;

function parseBlocks(javacOut) {
  const out = [];
  let m;
  BLOCK.lastIndex = 0;
  while ((m = BLOCK.exec(javacOut))) {
    const [, file, line, code, pre, kind, name, args, location] = m;
    out.push({ file, line: parseInt(line, 10), code, col: pre.length, kind, name, argc: kind === "method" ? (args && args.trim() ? splitTop(args).length : 0) : null, location: (location || "").trim() });
  }
  return out;
}

function resolveSimple(simpleName, src, v, deps) {
  const imp = new RegExp(`^\\s*import\\s+([\\w.]+\\.${simpleName})\\s*;`, "m").exec(src);
  if (imp) return imp[1];
  const c = (deps.classIndex(v).get(simpleName) || []).filter((f) => API_PKG.test(f));
  return c.length === 1 ? c[0] : null;
}

/** The type javac's `location:` line names, as an API fqn (or null for the plugin's own types). */
function locationType(loc, src, v, deps) {
  let m = /^(?:class|interface|enum)\s+([\w.$]+)/.exec(loc);
  if (!m) m = /^variable\s+\w+\s+of type\s+([\w.$]+)/.exec(loc);
  if (!m) return null;
  const t = m[1].replace(/<.*$/, "");
  if (t.includes(".")) return API_PKG.test(t) ? t : null;
  if (new RegExp(`\\b(class|interface|enum|record)\\s+${t}\\b`).test(src)) return null;
  return resolveSimple(t, src, v, deps);
}

/**
 * deps: { classIndex(v) -> Map(simple -> [fqn]), getClass?(v, fqn) -> rec|null, packageClasses?(v, pkg) -> [fqn] }
 * Returns { fixes: [{file, line, kind, from, to}] }; files are rewritten in place. Only exact, unambiguous edits.
 */
function fixMembers(javacOut, ws, v, deps = {}) {
  const get = deps.getClass || ((vv, f) => getClass(vv, f));
  const pkgClasses = deps.packageClasses || ((vv, p) => packageClasses(vv, p, { classIndex: deps.classIndex }));
  const fixes = [];
  const files = new Map(); // rel -> {abs, src}
  const load = (rel) => {
    if (files.has(rel)) return files.get(rel);
    if (!rel.startsWith("src/main/java/") || rel.includes("..")) return null;
    const abs = path.join(ws, rel);
    let src; try { src = fs.readFileSync(abs, "utf8"); } catch { return null; }
    const e = { abs, src, dirty: false };
    files.set(rel, e);
    return e;
  };
  const replaceAt = (e, line, col, from, to) => {
    const lines = e.src.split("\n");
    const L = lines[line - 1];
    if (L === undefined) return false;
    // the identifier starts at or just after the caret column (`.name(` puts the caret on the dot)
    const re = new RegExp(`\\b${from}\\b`, "g");
    let hit = -1, m;
    while ((m = re.exec(L))) { if (m.index >= col - 1 && m.index <= col + 4) { hit = m.index; break; } if (hit < 0 && m.index > col) hit = m.index; }
    if (hit < 0) return false;
    lines[line - 1] = L.slice(0, hit) + to + L.slice(hit + from.length);
    e.src = lines.join("\n"); e.dirty = true;
    return true;
  };
  const renameTokens = (e, from, to) => {
    const T = J.parse(e.src);
    if (!T) return 0;
    const hits = T.toks.filter((t, i) => t.t === "id" && t.v === from && !(T.toks[i - 1] && T.toks[i - 1].t === "op" && T.toks[i - 1].v === "." && !/^[A-Z]/.test(from)));
    let out = e.src;
    for (const t of hits.reverse()) out = out.slice(0, t.s) + to + out.slice(t.e);
    if (hits.length) { e.src = out; e.dirty = true; }
    return hits.length;
  };

  const seen = new Set();
  for (const b of parseBlocks(javacOut)) {
    const e = load(b.file);
    if (!e) continue;
    const key = `${b.file}|${b.line}|${b.kind}|${b.name}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const lineText = e.src.split("\n")[b.line - 1] || "";
    if (b.kind === "class") {
      const imp = /^\s*import\s+([\w.]+)\.(\w+)\s*;\s*$/.exec(lineText);
      let pkg = null;
      if (imp && imp[2] === b.name) pkg = imp[1];
      else {
        const lp = /^package\s+([\w.]+)/.exec(b.location);
        if (lp && imp) pkg = lp[1];
      }
      if (!pkg) continue;
      if (!API_PKG.test(`${pkg}.`)) continue;
      const pool = pkgClasses(v, pkg).map((f) => f.slice(f.lastIndexOf(".") + 1));
      if (!pool.length || pool.includes(b.name)) continue;
      const p = pick(b.name, pool);
      if (!p) continue;
      // never collide with something the file already declares or imports under that name
      if (new RegExp(`\\b(class|interface|enum|record)\\s+${p.name}\\b`).test(e.src)) continue;
      if (new RegExp(`^\\s*import\\s+[\\w.]+\\.${p.name}\\s*;`, "m").test(e.src)) continue;
      const n = renameTokens(e, b.name, p.name);
      if (n) fixes.push({ file: b.file, line: b.line, kind: "did-you-mean-class", from: `${pkg}.${b.name}`, to: `${pkg}.${p.name}` });
      continue;
    }
    const fqn = locationType(b.location, e.src, v, deps);
    if (!fqn) continue;
    const pool = memberPool(v, fqn, b.kind, get, b.argc);
    if (!pool || !pool.names.length) continue;
    if (pool.names.includes(b.name)) continue; // exists with another arity: a real bug for the model
    const p = pick(b.name, pool.names);
    if (!p) continue;
    // same-name constant on a different type is not what javac asked about; the edit is the one identifier at the caret
    if (replaceAt(e, b.line, b.col, b.name, p.name)) {
      fixes.push({ file: b.file, line: b.line, kind: b.kind === "method" ? "did-you-mean-method" : "did-you-mean-member", from: `${simple(fqn)}.${b.name}`, to: `${simple(fqn)}.${p.name}` });
    }
  }
  for (const [, e] of files) if (e.dirty) fs.writeFileSync(e.abs, e.src);
  return { fixes };
}

// ------------------------------------------------------------------------------------------------- hints
/**
 * The relevant members of ONE type for a missing member / method, as one line for the repair prompt. null when the type is
 * unknown. kind: variable | method. At most `max` names, ranked by shared words with the wanted name, then edit distance.
 */
function hint(v, fqn, kind, name, argc = null, opts = {}) {
  const get = opts.getClass || ((vv, f) => getClass(vv, f));
  const pool = memberPool(v, fqn, kind, get, null);
  if (!pool || !pool.names.length) return null;
  const max = opts.max || 12;
  const ww = new Set(words(name));
  const wf = flat(name);
  const exactArity = kind === "method" && argc !== null ? new Set(memberPool(v, fqn, kind, get, argc).names) : null;
  const ranked = pool.names
    .map((n) => {
      const nw = words(n);
      const shared = nw.filter((w) => ww.has(w)).length;
      return { n, shared, d: lev(wf, flat(n)), ar: exactArity ? (exactArity.has(n) ? 0 : 1) : 0 };
    })
    .sort((a, b) => b.shared - a.shared || a.ar - b.ar || a.d - b.d || a.n.localeCompare(b.n));
  const top = ranked.filter((x) => x.shared > 0 || x.d <= Math.max(3, Math.floor(wf.length / 3))).slice(0, max);
  const list = (top.length ? top : ranked.slice(0, Math.min(max, 8))).map((x) => x.n);
  const s = simple(fqn);
  const total = pool.names.length;
  if (kind === "variable") return `- ${s} has no ${name} in Paper ${v} (it has ${total} fields/constants). The closest real ones: ${list.join(", ")}.${total > list.length ? " Pick one of these or use a different type." : ""}`;
  return `- ${s}.${name}(${argc === null ? "..." : `${argc} arg${argc === 1 ? "" : "s"}`}) does not exist in Paper ${v}. The closest real methods: ${list.join(", ")}.`;
}

module.exports = { enabled, parseJavap, getClass, fromRecords, packageClasses, loadFile, lev, pick, memberPool, parseBlocks, fixMembers, hint, ancestry, words };

