"use strict";
// Workspace map for CHANGE builds (Cyrus structure round, card 2; MB_WORKSPACE_MAP=1, default OFF).
//
// Change builds are 44% of spend and 12-31 turns each (BL): the change prompt said "Read the existing files you need first", so the
// model spent its first turns listing and reading the project to find out what is in it. This module builds a compact outline
// of the project that is already in the working directory and puts it into the FIRST user turn:
//
//   plugin.yml        name, version, main, api-version, depend / softdepend, commands (+ permission), permission nodes
//   config.yml        flattened keys with their defaults (capped)
//   java files        per type: kind, name, extends / implements, annotations; public + protected method signatures, event
//                     handlers (@EventHandler -> event type), getCommand("x") registrations, non-private fields; private
//                     methods by name only
//   assets            file names under assets/ (designs, textures, sounds, creatures, config), modbuilder.json "changes" (last 3)
//
// Signatures only, never bodies. A hard cap (MB_WORKSPACE_MAP_TOKENS, default 2500 estimated tokens at 3.6 chars per token)
// picks the most detailed level that fits, falling back to ever shorter ones. The map is deterministic for a given workspace (sorted
// paths), so it sits in the cacheable prefix of the turn. The model must still Read a file before it edits it.

const fs = require("fs");
const path = require("path");
const J = require("./javaast");

const enabled = (env = process.env) => /^(1|true|on|yes)$/i.test(String(env.MB_WORKSPACE_MAP ?? "").trim());
const CHARS_PER_TOKEN = 3.6;
const capTokens = (env = process.env) => { const n = parseInt(env.MB_WORKSPACE_MAP_TOKENS, 10); return n > 200 ? n : 2500; };
const estTokens = (s) => Math.ceil(String(s).length / CHARS_PER_TOKEN);

function listFiles(dir, base = dir, out = []) {
  let ents = [];
  try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of ents.sort((a, b) => a.name.localeCompare(b.name))) {
    if (e.name === "build" || e.name === ".gradle" || e.name === "reference" || e.name === "nxperf" || e.name.startsWith(".")) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) listFiles(p, base, out); else out.push(path.relative(base, p));
  }
  return out;
}

const short = (s, n) => (String(s).length > n ? `${String(s).slice(0, n - 1)}…` : String(s));

function flatten(obj, prefix, out, cap) {
  for (const [k, v] of Object.entries(obj || {})) {
    if (out.length >= cap) return;
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === "object" && !Array.isArray(v)) flatten(v, key, out, cap);
    else if (Array.isArray(v)) out.push(`${key}=[${v.length}]`);
    else out.push(`${key}=${short(typeof v === "string" ? JSON.stringify(v) : String(v), 24)}`);
  }
}

function readYaml(file, YAML) {
  try { return YAML.parse(fs.readFileSync(file, "utf8")); } catch { return null; }
}

/** The structured facts of the workspace (no rendering). */
function collect(ws, YAML) {
  const facts = { plugin: null, config: [], files: [], assets: [], changes: [], note: null };
  const yml = readYaml(path.join(ws, "src/main/resources/plugin.yml"), YAML);
  if (yml && typeof yml === "object") {
    const cmds = Object.entries(yml.commands || {}).map(([n, c]) => ({ name: n, desc: c && c.description ? short(c.description, 60) : "", perm: c && c.permission ? c.permission : "", aliases: c && c.aliases ? [].concat(c.aliases) : [] }));
    const perms = Object.keys(yml.permissions || {});
    facts.plugin = { name: yml.name, version: yml.version, main: yml.main, api: yml["api-version"], depend: yml.depend, softdepend: yml.softdepend, cmds, perms };
  }
  const cfg = readYaml(path.join(ws, "src/main/resources/config.yml"), YAML);
  if (cfg && typeof cfg === "object") { flatten(cfg, "", facts.config, 80); facts.config = facts.config.filter((k) => !/^perf\./.test(k)); }
  const javaRoot = path.join(ws, "src/main/java");
  const rels = listFiles(javaRoot).filter((f) => f.endsWith(".java"));
  for (const rel of rels) {
    let src; try { src = fs.readFileSync(path.join(javaRoot, rel), "utf8"); } catch { continue; }
    const o = J.outline(src);
    const regs = [];
    for (const m of src.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) regs.push(m[1]);
    facts.files.push({ rel: `src/main/java/${rel}`, lines: src.split("\n").length, outline: o, commands: [...new Set(regs)], isMain: !!(facts.plugin && facts.plugin.main && `${facts.plugin.main.replace(/\./g, "/")}.java` === rel) });
  }
  facts.files.sort((a, b) => (b.isMain ? 1 : 0) - (a.isMain ? 1 : 0) || a.rel.localeCompare(b.rel));
  const assetFiles = listFiles(path.join(ws, "assets")).map((f) => `assets/${f}`);
  facts.assets = assetFiles;
  try {
    const mj = JSON.parse(fs.readFileSync(path.join(ws, "modbuilder.json"), "utf8"));
    const ch = Array.isArray(mj.changes) ? mj.changes : [];
    facts.changes = ch.slice(-3).map((c) => short(typeof c === "string" ? c : c && (c.summary || c.text || c.description) ? c.summary || c.text || c.description : JSON.stringify(c), 120));
  } catch { /* none */ }
  return facts;
}

const sigOf = (m, level) => {
  const params = m.params.map((p) => (level <= 1 ? `${p.type} ${p.name}`.trim() : p.type || p.name)).join(", ");
  return `${m.name}(${params})${m.ret && m.ret !== "void" ? `: ${m.ret}` : ""}`;
};

function renderType(t, level, indent) {
  const pad = "  ".repeat(indent);
  const out = [];
  const head = `${t.kind} ${t.name}${t.ext ? ` extends ${t.ext}` : ""}${t.impls.length ? ` implements ${t.impls.join(", ")}` : ""}${t.constants.length ? ` {${t.constants.slice(0, 12).join(", ")}${t.constants.length > 12 ? ", …" : ""}}` : ""}`;
  out.push(`${pad}${head}`);
  const ann = new Map();
  const handlers = [];
  const pub = [];
  const priv = [];
  for (const m of t.methods) {
    const isPrivate = m.mods.includes("private");
    const handler = m.ann.includes("EventHandler");
    if (handler) { handlers.push(m); continue; }
    if (isPrivate || (!m.mods.includes("public") && !m.mods.includes("protected"))) priv.push(m); else pub.push(m);
  }
  void ann;
  if (level <= 3 && t.fields.length) {
    const fl = t.fields.filter((f) => level <= 1 ? true : !f.mods.includes("private") || !f.mods.includes("static")).slice(0, level <= 1 ? 24 : 12);
    if (fl.length) out.push(`${pad}  fields: ${fl.map((f) => `${f.name}:${short(f.type, 40)}`).join(", ")}`);
  }
  if (handlers.length) out.push(`${pad}  events: ${handlers.map((m) => `${m.params[0] ? m.params[0].type : "?"}${m.annArgs.some((a) => a.name === "EventHandler" && a.args) ? `(${short(m.annArgs.find((a) => a.name === "EventHandler").args, 30)})` : ""} -> ${m.name}`).join("; ")}`);
  if (pub.length) out.push(`${pad}  methods: ${pub.map((m) => (level <= 3 ? sigOf(m, level) : m.name)).join("; ")}`);
  if (priv.length && level <= 1) out.push(`${pad}  private: ${priv.map((m) => m.name).join(", ")}`);
  for (const n of t.nested) out.push(...renderType(n, level, indent + 1));
  return out;
}

/** Render the facts at one detail level (0 = most detail ... 4 = file list only). */
function render(facts, level) {
  const out = [];
  out.push("WORKSPACE MAP (generated by the build service from the files now in the working directory; signatures only, no bodies. Paths are relative to the working directory. You must still Read a file before you edit it.)");
  const p = facts.plugin;
  if (p) {
    out.push(`plugin.yml: name=${p.name} version=${p.version} main=${p.main}${p.api ? ` api-version=${p.api}` : ""}${p.depend ? ` depend=${JSON.stringify(p.depend)}` : ""}${p.softdepend ? ` softdepend=${JSON.stringify(p.softdepend)}` : ""}`);
    if (p.cmds.length) out.push(`commands: ${p.cmds.map((c) => `/${c.name}${c.aliases.length ? `(${c.aliases.join(",")})` : ""}${c.perm ? ` [${c.perm}]` : ""}${level <= 1 && c.desc ? ` "${c.desc}"` : ""}`).join("; ")}`);
    if (p.perms.length) out.push(`permissions: ${p.perms.join(", ")}`);
  }
  if (facts.config.length && level <= 3) out.push(`config.yml keys: ${facts.config.slice(0, level <= 1 ? 80 : 40).join(", ")}${facts.config.length > (level <= 1 ? 80 : 40) ? ", …" : ""}`);
  for (const f of facts.files) {
    out.push(`${f.rel} (${f.lines} lines)${f.isMain ? " [main class]" : ""}${f.commands.length ? ` registers /${f.commands.join(", /")}` : ""}`);
    if (level >= 4 || !f.outline) continue;
    for (const t of f.outline.types) out.push(...renderType(t, level, 1));
  }
  if (facts.assets.length) out.push(`assets: ${facts.assets.slice(0, 40).join(", ")}${facts.assets.length > 40 ? `, … (${facts.assets.length} files)` : ""}`);
  if (facts.changes.length) out.push(`recent changes (modbuilder.json): ${facts.changes.join(" | ")}`);
  return out.join("\n");
}

/**
 * Build the map for a workspace. Returns { text, tokens, level, files, types, truncated } or null when there is nothing to map.
 * opts: { YAML, maxTokens, env }
 */
function build(ws, opts = {}) {
  const env = opts.env || process.env;
  const YAML = opts.YAML || require("yaml");
  const cap = opts.maxTokens || capTokens(env);
  let facts;
  try { facts = collect(ws, YAML); } catch { return null; }
  if (!facts.files.length && !facts.plugin) return null;
  let text = "", level = 0;
  for (level = 0; level <= 4; level++) {
    text = render(facts, level);
    if (estTokens(text) <= cap) break;
  }
  let truncated = false;
  if (estTokens(text) > cap) {
    // even the file list does not fit: keep the head, say so
    truncated = true;
    text = `${text.slice(0, Math.floor(cap * CHARS_PER_TOKEN) - 80)}\n… (map cut at ${cap} tokens; ${facts.files.length} source files in total)`;
    level = 5;
  }
  const types = facts.files.reduce((n, f) => n + (f.outline ? f.outline.types.length : 0), 0);
  return { text, tokens: estTokens(text), level, files: facts.files.length, types, truncated };
}

module.exports = { enabled, build, collect, render, estTokens, capTokens, CHARS_PER_TOKEN };

