}''','''/** Indentation-based reader for the plain YAML plugins use (maps, scalars, "- x" lists, [a, b] flow lists). Fallback only. */
function miniParse(text) {
  const root = {};
  const stack = [{ indent: -1, obj: root }];
  const scalar = (v) => {
    v = v.replace(/\\s+#.*$/, "").trim();
    if (/^(["']).*\\1$/.test(v)) return v.slice(1, -1);
    if (/^\\[.*\\]$/.test(v)) return v.slice(1, -1).split(",").map((x) => scalar(x)).filter((x) => x !== "");
    if (v === "true") return true;
    if (v === "false") return false;
    if (v !== "" && !isNaN(Number(v))) return Number(v);
    return v;
  };
  let lastKey = null;
  for (const raw of String(text).split("\\n")) {
    if (!raw.trim() || /^\\s*#/.test(raw)) continue;
    const indent = raw.length - raw.trimStart().length;
    const line = raw.trim();
    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) stack.pop();
    const top = stack[stack.length - 1];
    if (line.startsWith("- ")) {
      if (lastKey && top.obj[lastKey] !== undefined && !Array.isArray(top.obj[lastKey])) top.obj[lastKey] = [];
      if (lastKey && Array.isArray(top.obj[lastKey])) top.obj[lastKey].push(scalar(line.slice(2)));
      continue;
