    const m = /^("[^"]*"|'[^']*'|[^:]+?)\\s*:\\s*(.*)$/.exec(line);
    if (!m) continue;
    const key = m[1].replace(/^["']|["']$/g, "");
    if (m[2] === "" ) {
      top.obj[key] = {};
      stack.push({ indent, obj: top.obj[key], parent: top.obj, key });
      lastKey = key;
      // a "- " list under this key replaces the empty map
      const holder = stack[stack.length - 1];
      holder.listFor = true;
