export type DesignerPart = (typeof DESIGNER_PARTS)[number];

export type EvalPrompt = {
  key: string; v: string; cls: "simple" | "standard" | "complex"; prompt: string; category: string; route: string;
  checks: string[]; must_refuse: boolean; adversarial?: boolean; rt?: boolean; versions?: string[];
  assetKinds?: string[]; designer?: DesignerPart[]; tier?: string; capability?: string; baseKey?: string; legacy?: boolean;
  /** bundle mc-coverage (sets/coverage.jsonl): the coverage-matrix archetype, the planner lanes it should select,
   * what a correct build looks like (build | limited = build with a stated limit | limit-only = no lane can do it), the
   * Paper event it exercises. */
  archetype?: string; expectLanes?: string[]; expectOutcome?: "build" | "limited" | "limit-only"; event?: string;
  /** feature/cyrus-mc-techniques (sets/techniques.jsonl, scored by ./techniques.ts): the switches the build needs, a
   * reference golden (design fixture or golden plugin dir), what a correct design / plugin / lane spec must contain. */
  switches?: string[]; golden?: string; rule?: string; constrain?: string;
  expectDesign?: { trigger: string; actions: string[]; blocks?: string[]; conditions?: string[] };
  expectApi?: string[]; expectSpec?: string; expectLimit?: string;
  /** sets/assets.jsonl asset-quality prompts (2026-10-14): the failure shape the prompt is aimed at and what a good build ships
   * (minimum textures / sound events, minimum quality score, no repair). Reported by score.ts `assetExpectationMisses`. */
  failureShape?: string;
  expectAssets?: { textures?: { min: number; minQuality?: number }; sounds?: { minEvents: number; minQuality?: number }; firstAttempt?: boolean };
};
