HDR = """package dev.nxeon.plugins.structure;

import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitRunnable;
"""
shapes = {
"S01Plain": ("fourth1 ast-ruby-sword / ast-banshee-full (BS report evidence line): plain braced for, the only shape the old autofix handled",
"""  void giveBack(Player target, List<ItemStack> leftover) {
    for (ItemStack extra : leftover) {
      target.getWorld().dropItemNaturally(target.getLocation(), extra);
    }
  }"""),
"S02Leftover": ("golden mc-crates / mc-joinleave / mc-mobcatcher: leftover items through forEach lambda (old rule saw no loop: no brace)",
"""  void reward(Player p, ItemStack item) {
    p.getInventory().addItem(item).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
  }"""),
"S03Chunks": ("test-flight fixture chunkmirror-unbounded (the ChunkMirror incident): spawn per loaded chunk, impure first argument",
"""  void mirror(World w, Location at, EntityType t) {
    for (Chunk c : w.getLoadedChunks()) {
      if (c.getX() == at.getChunk().getX() && c.getZ() == at.getChunk().getZ()) continue;
      w.spawnEntity(c.getBlock(8, at.getBlockY(), 8).getLocation().add(0.5, 0, 0.5), t);
    }
  }"""),
"S04DeclUsed": ("test-flight fixture creature: spawned entity assigned and configured after the call (variable used later)",
"""  void pack(World world, Location base, int n) {
    for (int i = 0; i < n; i++) {
      Location at = base.clone().add((i % 10) * 2.5, 0, (i / 10) * 2.5);
      LivingEntity mob = (LivingEntity) world.spawnEntity(at, EntityType.ZOMBIE);
      mob.setSilent(true);
      mob.setPersistent(true);
      if (mob instanceof Zombie z) { z.setShouldBurnInDay(false); z.setAdult(); }
    }
  }"""),
"S05Braceless": ("generated shape seen in first1 repairs: braceless enhanced for",
"""  void rain(World world, List<Location> spots) {
    for (Location spot : spots) world.spawnEntity(spot, EntityType.CHICKEN);
  }"""),
"S06While": ("while loop with a counter and a declaration used afterwards",
"""  void wave(World w, Location l, int count) {
    int left = count;
    while (left > 0) {
      Entity e = w.spawnEntity(l, EntityType.BAT);
      e.setCustomName("wave");
      left--;
    }
  }"""),
"S07DoWhile": ("do-while with a drop",
"""  void burst(World w, Location l, ItemStack stack) {
    int i = 0;
    do {
      w.dropItem(l, stack);
      i++;
    } while (i < 5);
  }"""),
"S08Nested": ("golden mc-joinleave + nested: a forEach inside a for loop",
"""  void kits(Collection<? extends Player> players, List<ItemStack> kit) {
    for (Player p : players) {
      for (ItemStack it : kit) {
        p.getInventory().addItem(it).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
      }
    }
  }"""),
"S09StreamBlock": ("stream pipeline with a block lambda and a declaration used inside it",
"""  void spawnAround(World world, List<Player> players) {
    players.stream().filter(p -> p.isOnline()).forEach(p -> {
      Zombie z = world.spawn(p.getLocation(), Zombie.class);
      z.setBaby(true);
    });
  }"""),
"S10TimerLambda": ("scheduler timer lambda, 2 tick period (spawn trail)",
"""  void trail(JavaPlugin plugin, Player p) {
    Bukkit.getScheduler().runTaskTimer(plugin, () -> {
      p.getWorld().spawnEntity(p.getLocation(), EntityType.EXPERIENCE_ORB);
    }, 0L, 2L);
  }"""),
"S11AnonRunnable": ("new BukkitRunnable() { run() } .runTaskTimer, 1 tick period, drop in run()",
"""  void rainItems(JavaPlugin plugin, Location l, ItemStack stack) {
    new BukkitRunnable() {
      @Override public void run() {
        l.getWorld().dropItemNaturally(l, stack);
      }
    }.runTaskTimer(plugin, 0L, 1L);
  }"""),
"S12Summon": ("summon through a console command in a loop",
"""  void summon(int n) {
    for (int i = 0; i < n; i++) {
      Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "summon minecraft:zombie ~ ~ ~");
    }
  }"""),
"S13ExprLambda": ("expression lambda body in forEach (no braces at all)",
"""  void drops(World world, List<Location> spots, ItemStack stack) {
    spots.forEach(s -> world.dropItem(s, stack));
  }"""),
"S14BracelessIf": ("braceless if inside a loop: the guard must not capture the else",
"""  void maybe(World w, List<Location> spots, boolean rare) {
    for (Location s : spots)
      if (rare) w.spawnEntity(s, EntityType.PARROT);
      else w.spawnEntity(s, EntityType.PIG);
  }"""),
"S15Break": ("golden mc-crops: first drop doubled then break (a loop that runs once, still a loop)",
"""  void harvest(org.bukkit.block.Block b, List<ItemStack> drops) {
    for (ItemStack drop : drops) {
      if (drop.getType().name().endsWith("_SEEDS")) continue;
      b.getWorld().dropItemNaturally(b.getLocation().add(0.5, 0.2, 0.5), drop.asOne());
      break;
    }
  }"""),
}
for name,(prov,body) in shapes.items():
    open(f"{name}.java","w").write(f"""{HDR}
/** Source of the shape: {prov}. */
final class {name} {{
{body}
}}
""")
# negatives (must stay untouched / be skipped)
neg = {
"N01Guarded": ("already bounded: spawnAllowed in the condition", """  void ok(World w, List<Location> spots) {
    for (Location s : spots) {
      if (NxPerf.spawnAllowed("ok", s.getChunk())) { w.spawnEntity(s, EntityType.PIG); }
    }
  }"""),
"N02EarlyOut": ("already bounded: negative guard with continue", """  void ok(World w, List<Location> spots) {
    for (Location s : spots) {
      if (!NxPerf.spawnAllowed("ok", null)) continue;
      w.spawnEntity(s, EntityType.PIG);
    }
  }"""),
"N03SlowTimer": ("a timer with a 20 tick period is a feature, not a flood", """  void slow(JavaPlugin plugin, Location l) {
    Bukkit.getScheduler().runTaskTimer(plugin, () -> l.getWorld().spawnEntity(l, EntityType.BAT), 0L, 20L);
  }"""),
"N04NoLoop": ("a single spawn in a handler", """  void once(World w, Location l) {
    w.spawnEntity(l, EntityType.PIG);
  }"""),
"N05ValueLambda": ("value lambda: left for the model (a guard would change the result)", """  List<Entity> make(World w, List<Location> spots) {
    return spots.stream().map(s -> w.spawnEntity(s, EntityType.PIG)).toList();
  }"""),
"N06Condition": ("call inside a loop condition: left for the model", """  void odd(World w, Location l) {
    for (int i = 0; w.spawnEntity(l, EntityType.PIG) != null && i < 3; i++) { }
  }"""),
}
for name,(prov,body) in neg.items():
    imp = "import dev.nxeon.plugins.structure.nxperf.NxPerf;\n" if name in ("N01Guarded","N02EarlyOut") else ""
    open(f"{name}.java","w").write(f"""{HDR}{imp}
/** Negative case: {prov}. */
final class {name} {{
{body}
}}
""")
E
