      // the "before" file needs the NxPerf import only when the fixture itself uses it (negative cases do)
      writeFileSync(`${before}/${pkg.replace(/\./g, "/")}/${n}`, src);
      const r = AP.rewrite(src, n.replace(".java", ""));
      let text = r.text;
      if (r.fixes.length && !/import dev\.nxeon\.plugins\.structure\.nxperf\.NxPerf;/.test(text)) text = text.replace(/^(package [^;]+;\s*)/m, `$1\nimport ${pkg}.nxperf.NxPerf;\n`);
      writeFileSync(`${after}/${pkg.replace(/\./g, "/")}/${n}`, text);
      const filesOf = (d: string) => { const out: string[] = []; const walk = (p: string) => { for (const e of readdirSync(p, { withFileTypes: true })) { const q = path.join(p, e.name); if (e.isDirectory()) walk(q); else if (q.endsWith(".java")) out.push(q); } }; walk(d); return out; };
      const b = javac(filesOf(before), v, `${dir}/before/classes`);
      const a = javac(filesOf(after), v, `${dir}/after/classes`);
      const left = AP.detect(text).findings.length;
      rows.push({ version: v, fixture: n, fixes: r.fixes.length, skipped: r.skipped.map((s: { reason: string }) => s.reason), left, compileBefore: b.ok, compileAfter: a.ok, errorAfter: a.ok ? undefined : a.errors });
    }
  }
  const bad = rows.filter((r) => r.compileBefore && !r.compileAfter);
  console.log(`perf: ${rows.length} compiles (${names.length} fixtures x ${VERSIONS.length} versions); rewritten fixtures that stopped compiling: ${bad.length}`);
  for (const b of bad) console.log("  BROKEN", b.version, b.fixture, b.errorAfter);
  return { rows, broken: bad.length };
}

function index() {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const MI = require("../services/modbuilder/memberindex.js");
  const dir = `${RUN}/classpath`;
  mkdirSync(dir, { recursive: true });
  const stats: Record<string, unknown>[] = [];
  for (const v of VERSIONS) {
    const cp = readFileSync(`${TF}/classpath/${v}.txt`, "utf8").replace(/\n/g, "").trim();
    writeFileSync(`${dir}/${v}.txt`, cp);
    const names = new Set<string>();
    for (const j of cp.split(":")) { try { for (const l of execFileSync(`${JDK}/bin/jar`, ["tf", j], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024 }).split("\n")) if (l.endsWith(".class")) names.add(l); } catch { /* skip */ } }
    writeFileSync(`${dir}/${v}.classes.txt`, [...names].sort().join("\n"));
    const t0 = Date.now();
    const out = execFileSync("node", [path.join(ROOT, "services/modbuilder/tools/gen-member-index.js"), v, dir, path.join(ROOT, "services/modbuilder")], { encoding: "utf8", env: { ...process.env, JAVA_HOME: JDK } });
    stats.push({ version: v, line: out.trim(), ms: Date.now() - t0 });
    console.log(out.trim());
  }
  // ---- did-you-mean on mutated real names
  const results: Record<string, unknown>[] = [];
  const TYPES: [string, string][] = [["org.bukkit.Material", "variable"], ["org.bukkit.Sound", "variable"], ["org.bukkit.entity.EntityType", "variable"], ["org.bukkit.attribute.Attribute", "variable"], ["org.bukkit.Particle", "variable"], ["org.bukkit.potion.PotionEffectType", "variable"], ["org.bukkit.entity.Player", "method"], ["org.bukkit.World", "method"], ["org.bukkit.inventory.meta.ItemMeta", "method"], ["org.bukkit.inventory.ItemStack", "method"]];
  const rnd = (seed: number) => () => (seed = (seed * 1664525 + 1013904223) % 4294967296) / 4294967296;
  const rand = rnd(7);
  const mutate = (s: string, kind: "variable" | "method"): string[] => {
    const out: string[] = [];
    const i = Math.max(1, Math.floor(rand() * (s.length - 1)));
    out.push(s.slice(0, i) + s.slice(i + 1)); // dropped char
    out.push(s.slice(0, i) + s[i] + s.slice(i)); // doubled char
    if (kind === "variable") {
      out.push(s.replace(/^GENERIC_/, ""));
      out.push(s + "S");
      const parts = s.split("_");
      if (parts.length >= 3) out.push(parts.slice(0, -1).join("_")); // dropped last word
    } else {
      out.push(s.replace(/^get/, "") || s);
      out.push(s.replace(/s$/, ""));
    }
    return out.filter((x) => x && x !== s);
  };
  for (const v of VERSIONS) {
    const f = MI.loadFile(v, dir);
    if (!f) continue;
    let total = 0, fixedRight = 0, fixedWrong = 0, ambiguous = 0;
    const wrong: string[] = [];
    for (const [fqn, kind] of TYPES) {
      const cls = f.classes[fqn];
      if (!cls) continue;
      const pool = kind === "variable" ? [...cls.c, ...cls.f] : [...new Set((cls.m as [string, number][]).map((m) => m[0]))].filter((n: string) => !/^(equals|hashCode|toString|getClass|wait|notify|notifyAll)$/.test(n));
      const sample = pool.filter((_: string, i: number) => i % Math.max(1, Math.floor(pool.length / 120)) === 0);
      for (const real of sample) {
        for (const bad of mutate(real, kind)) {
          if (pool.includes(bad)) continue; // the mutation is itself a real name
          total++;
          const p = MI.pick(bad, pool);
          if (!p) ambiguous++;
          else if (p.name === real) fixedRight++;
          else { fixedWrong++; if (wrong.length < 12) wrong.push(`${v} ${fqn.split(".").pop()}: ${bad} -> ${p.name} (wanted ${real})`); }
        }
      }
    }
    results.push({ version: v, total, fixedRight, fixedWrong, ambiguous, precisionPct: fixedRight + fixedWrong ? Math.round((fixedRight / (fixedRight + fixedWrong)) * 1000) / 10 : null, coveragePct: Math.round((fixedRight / total) * 1000) / 10, wrong });
    console.log(`${v}: ${total} mutated names, fixed right ${fixedRight}, fixed WRONG ${fixedWrong}, left to the model ${ambiguous}`);
  }
  // ---- the seen hallucinations on the real index (1.21.11)
  const probe: Record<string, unknown> = {};
  const f11 = MI.loadFile("1.21.11", dir);
  if (f11) {
    const classes = Object.keys(f11.classes);
    probe.consumeLike = classes.filter((c) => /Consum\w*Effect|ConsumableEffect/i.test(c.split(".").pop()!));
    const mat = f11.classes["org.bukkit.Material"];
    probe.materialSmithing = mat ? mat.c.filter((n: string) => /SMITHING_TEMPLATE/.test(n)).length : null;
    probe.pickSmithing = MI.pick("SMITHING_TEMPLATE", mat ? mat.c : []);
    const hint = MI.hint("1.21.11", "org.bukkit.Material", "variable", "SMITHING_TEMPLATE", null, { getClass: (_v: string, q: string) => f11.classes[q] ?? null });
    probe.hint = hint;
    probe.hintChars = hint ? hint.length : null;
    probe.oldHintChars = (`- Material has no SMITHING_TEMPLATE in Paper 1.21.11. It has: ${(mat ? mat.c : []).slice(0, 40).join(", ")}, ...`).length;
    probe.materialConstants = mat ? mat.c.length : null;
  }
  return { stats, results, probe };
}

