function fixListSubtype(javacOut, ws) {
  const fixes = [];
  const re = /^([^\s:]+\.java):(\d+): error: incompatible types: List<([^\n<>]+)> cannot be converted to List<([^\n<>]+)>\s*$/gm;
  const done = new Set();
  let m;
  while ((m = re.exec(javacOut))) {
    const [, file, lineNo, , want] = m;
    if (!file.startsWith("src/main/java/") || file.includes("..") || done.has(`${file}:${lineNo}`)) continue;
    if (!/^[A-Za-z_][\w.]*$/.test(want)) continue;
    const abs = path.join(ws, file);
    let src; try { src = fs.readFileSync(abs, "utf8"); } catch { continue; }
    const lines = src.split("\n");
    const li = parseInt(lineNo, 10) - 1;
    if (li < 0 || li >= lines.length) continue;
    const from = lines[li];
    if ((from.match(/\.toList\(\)/g) || []).length !== 1) continue;
    lines[li] = from.replace(".toList()", `.collect(java.util.stream.Collectors.<${want}>toList())`);
    fs.writeFileSync(abs, lines.join("\n"));
    done.add(`${file}:${lineNo}`);
    fixes.push({ file, line: li + 1, kind: "list-subtype", from: from.trim().slice(0, 160), to: lines[li].trim().slice(0, 160) });
  }
  return { fixes };
}

