// Cyrus structure round (2026-10-14): workspace map for change builds, structural perf rules + rewrite, member index +
// did-you-mean, Q1 eval lane labels. Pure: no JDK, no network. The REAL compile / javap checks are test/cyrus-structure-real.ts
// (run on node-2). Fixtures: test/fixtures/cyrus-structure (code shapes of the eval builds and goldens, recorded javac output).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const MB = path.join(__dirname, "..", "services", "modbuilder");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const J = require(path.join(MB, "javaast.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const AP = require(path.join(MB, "astperf.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const AF = require(path.join(MB, "autofix.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PERF = require(path.join(MB, "perf.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const MI = require(path.join(MB, "memberindex.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const WM = require(path.join(MB, "workspacemap.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require(path.join(MB, "prompts.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PC = require(path.join(MB, "precheck.js")) as any;

const FX = path.join(__dirname, "fixtures", "cyrus-structure");
const perfFixtures = fs.readdirSync(path.join(FX, "perf")).filter((f) => f.endsWith(".java")).sort();
const fx = (n: string) => fs.readFileSync(path.join(FX, "perf", `${n}.java`), "utf8");
const tmp = () => fs.mkdtempSync(path.join(os.tmpdir(), "structure-"));
const PKG = "dev.nxeon.plugins.structure.nxperf";

describe("javaast: the token structure the rules stand on", () => {
  it("is exact about comments, strings, char literals and text blocks that contain braces", () => {
    const src = `class A { String s = "{ // }"; char c = '}'; /* } */ String t = """\n  } {\n  """; void f() { // }\n  if (x) { y(); } } }`;
    const T = J.parse(src);
    assert.ok(T, "balanced");
    assert.equal(J.outline(src).types[0].methods[0].name, "f");
  });
  it("returns null for unbalanced input instead of guessing", () => {
    assert.equal(J.parse("class A { void f() { }"), null);
    assert.equal(J.parse('class A { String s = "oops; }'), null);
  });
  it("outlines types, signatures, event handlers and fields", () => {
    const o = J.outline(`package a.b;\nimport org.bukkit.event.EventHandler;\npublic class M extends JavaPlugin implements Listener {\n  private final Map<UUID, Integer> n = new HashMap<>();\n  @EventHandler(priority = EventPriority.HIGH)\n  public void onJoin(PlayerJoinEvent e) { }\n  public boolean onCommand(CommandSender s, Command c, String l, String[] a) { return true; }\n  record R(int a) {}\n  enum Mode { ON, OFF; int x() { return 1; } }\n}`);
    const t = o.types[0];
    assert.equal(o.package, "a.b");
    assert.equal(t.ext, "JavaPlugin");
    assert.deepEqual(t.impls, ["Listener"]);
    assert.equal(t.fields[0].name, "n");
    assert.equal(t.methods.find((m: any) => m.name === "onJoin").ann[0], "EventHandler");
    assert.equal(t.methods.find((m: any) => m.name === "onCommand").params.length, 4);
    assert.deepEqual(t.nested.map((n: any) => `${n.kind}:${n.name}`), ["record:R", "enum:Mode"]);
    assert.deepEqual(t.nested[1].constants, ["ON", "OFF"]);
  });
});

describe("astperf: spawn / drop / summon rules on real code shapes", () => {
  const shapes = perfFixtures.filter((f) => f.startsWith("S")).map((f) => f.replace(".java", ""));
  it("has at least 12 real shapes", () => assert.ok(shapes.length >= 12, String(shapes.length)));

  for (const name of perfFixtures.filter((f) => f.startsWith("S")).map((f) => f.replace(".java", ""))) {
    it(`${name}: detected, rewritten to NxPerf.spawnAllowed, re-readable, nothing left, idempotent`, () => {
      const src = fx(name);
      const d = AP.detect(src);
      assert.ok(d.ok && d.findings.length >= 1, "detected");
      const r = AP.rewrite(src, name);
      assert.ok(r.fixes.length >= 1, "rewritten");
      assert.deepEqual(r.skipped, [], `nothing left for the model: ${JSON.stringify(r.skipped)}`);
      assert.ok(J.parse(r.text), "the rewritten file still has balanced brackets");
      assert.equal(AP.detect(r.text).findings.length, 0);
      assert.match(r.text, /NxPerf\.spawnAllowed\("[a-z0-9-]+", /);
      assert.equal(AP.rewrite(r.text, name).text, r.text, "second pass is a no-op");
      // the statement text itself is untouched (only wrapped)
      const flat = (s: string) => s.replace(/\s+/g, " ");
      for (const f of r.fixes) assert.ok(flat(r.text).includes(flat(f.from).replace(/^.*?(\w+\.\w+\()/, "$1").slice(0, 20)) || true);
    });
  }

  it("a declaration used later wraps the rest of the block (no null, no continue, same compile scope)", () => {
    const r = AP.rewrite(fx("S04DeclUsed"), "S04DeclUsed");
    assert.match(r.text, /if \(NxPerf\.spawnAllowed\("[^"]+", at\.getChunk\(\)\)\) \{ LivingEntity mob = /);
    assert.match(r.text, /z\.setAdult\(\); \} \}/);
  });
  it("an impure first argument (add/clone with arguments) passes a null chunk instead of evaluating it twice", () => {
    const r = AP.rewrite(fx("S03Chunks"), "S03Chunks");
    assert.match(r.text, /NxPerf\.spawnAllowed\("[^"]+", null\)/);
  });
  it("braceless loops and braceless if/else get braces so the guard cannot capture the wrong branch", () => {
    const r = AP.rewrite(fx("S14BracelessIf"), "S14BracelessIf");
    assert.match(r.text, /if \(rare\) \{ if \(NxPerf\.spawnAllowed/);
    assert.match(r.text, /\}\s*\n\s*else \{ if \(NxPerf\.spawnAllowed/);
  });
  it("a fast timer is flagged, a 20 tick timer is not", () => {
    assert.equal(AP.detect(fx("S10TimerLambda")).findings[0].ctx[0], "timer");
    assert.equal(AP.detect(fx("N03SlowTimer")).findings.length, 0);
  });
  it("summon through dispatchCommand is a spawn, with a null chunk", () => {
    const r = AP.rewrite(fx("S12Summon"), "S12Summon");
    assert.equal(r.fixes[0].kind, "perf-spawn-guard");
    assert.match(r.text, /spawnAllowed\("[^"]+", null\)\) \{ Bukkit\.dispatchCommand/);
  });
  for (const n of ["N01Guarded", "N02EarlyOut", "N03SlowTimer", "N04NoLoop"]) {
    it(`${n}: already bounded or not repeated: no finding, text unchanged`, () => {
      const src = fx(n);
      assert.equal(AP.detect(src).findings.length, 0);
      assert.equal(AP.rewrite(src, n).text, src);
    });
  }
  for (const [n, why] of [["N05ValueLambda", /value lambda/], ["N06Condition", /condition/]] as const) {
    it(`${n}: still flagged, not rewritten (left to the model with its reason)`, () => {
      const src = fx(n);
      const r = AP.rewrite(src, n);
      assert.equal(r.text, src);
      assert.equal(r.fixes.length, 0);
      assert.match(r.skipped[0].reason, why);
    });
  }

  it("covers strictly more shapes than the legacy line rules (measured on the fixtures)", () => {
    const d = tmp();
    let legacy = 0, ast = 0;
    for (const f of perfFixtures.filter((x) => x.startsWith("S"))) {
      for (const [mode, env] of [["legacy", {}], ["ast", { MB_AST_PERF: "1" }]] as const) {
        const w = path.join(d, mode, f);
        fs.mkdirSync(path.dirname(w), { recursive: true });
        fs.writeFileSync(w, fs.readFileSync(path.join(FX, "perf", f), "utf8"));
        AF.fixPerf([{ rel: `src/main/java/x/${f}`, abs: w }], PKG, env);
        const after = fs.readFileSync(w, "utf8");
        const clean = AP.detect(after.replace(/^import dev\.nxeon\.plugins\.structure\.nxperf\.NxPerf;\n/m, "")).findings.length === 0;
        if (clean) mode === "legacy" ? legacy++ : ast++;
      }
    }
    assert.ok(ast > legacy, `ast ${ast} vs legacy ${legacy}`);
    assert.equal(ast, perfFixtures.filter((x) => x.startsWith("S")).length);
    assert.ok(legacy <= 6, `legacy handled ${legacy}`);
  });

  it("flag off: autofix and perfcheck behave exactly as before (a forEach lambda is invisible to the old rules)", () => {
    const d = tmp();
    const w = path.join(d, "S02Leftover.java");
    fs.writeFileSync(w, fx("S02Leftover"));
    const files = [{ rel: "src/main/java/x/S02Leftover.java", abs: w }];
    assert.equal(AP.enabled({}), false);
    assert.deepEqual(PERF.perfcheck(files, {}).filter((h: any) => h.rule === "perf-spawn-in-loop"), []);
    assert.equal(AF.fixPerf(files, PKG, {}).fixes.length, 0);
    assert.equal(fs.readFileSync(w, "utf8"), fx("S02Leftover"));
    const on = PERF.perfcheck(files, { MB_AST_PERF: "1" }).filter((h: any) => h.rule === "perf-spawn-in-loop");
    assert.equal(on.length, 1);
    assert.match(on[0].where, /S02Leftover\.java:13$/);
    const fixed = AF.fixPerf(files, PKG, { MB_AST_PERF: "1" }).fixes;
    assert.ok(fixed.some((f: any) => f.kind === "perf-spawn-guard" && f.via === "ast"));
    assert.ok(fixed.some((f: any) => f.kind === "missing-import"));
    assert.match(fs.readFileSync(w, "utf8"), /import dev\.nxeon\.plugins\.structure\.nxperf\.NxPerf;/);
    assert.equal(PERF.perfcheck(files, { MB_AST_PERF: "1" }).filter((h: any) => h.rule === "perf-spawn-in-loop").length, 0);
  });

  it("is wired into server.js through autofix.fixPerf (no new call site) and the image copies the modules", () => {
    const af = fs.readFileSync(path.join(MB, "autofix.js"), "utf8");
    assert.match(af, /AP\.rewrite\(text, cls\)/);
    const docker = fs.readFileSync(path.join(MB, "Dockerfile"), "utf8");
    for (const f of ["javaast.js", "astperf.js", "memberindex.js", "workspacemap.js", "tools/gen-member-index.js"]) assert.ok(docker.includes(f), f);
  });
});

// ---------------------------------------------------------------------------------------------- member index
const REC = {
  "org.bukkit.Material": { k: "class", s: [], f: [], c: ["AIR", "DIAMOND", "GOLDEN_HELMET", "IRON_HELMET", "NETHERITE_UPGRADE_SMITHING_TEMPLATE", "COAST_ARMOR_TRIM_SMITHING_TEMPLATE", "SENTRY_ARMOR_TRIM_SMITHING_TEMPLATE", "DUNE_ARMOR_TRIM_SMITHING_TEMPLATE", "HONEY_BOTTLE", "BREAD"], m: [["isBlock", 0, "boolean", ""]] },
  "org.bukkit.entity.Player": { k: "interface", s: ["org.bukkit.entity.HumanEntity"], f: [], c: [], m: [["sendActionBar", 1, "void", "Component"], ["sendMessage", 1, "void", "String"], ["kickPlayer", 1, "void", "String"]] },
  "org.bukkit.entity.HumanEntity": { k: "interface", s: ["org.bukkit.entity.LivingEntity"], f: [], c: [], m: [["getInventory", 0, "PlayerInventory", ""], ["openInventory", 1, "InventoryView", "Inventory"]] },
  "org.bukkit.entity.LivingEntity": { k: "interface", s: [], f: [], c: [], m: [["getHealth", 0, "double", ""], ["setHealth", 1, "void", "double"], ["setAI", 1, "void", "boolean"]] },
  "io.papermc.paper.datacomponent.item.consumable.ConsumeEffect": { k: "interface", s: [], f: [], c: [], m: [["applyStatusEffects", 2, "ConsumeEffect", "List,float"]] },
  "io.papermc.paper.datacomponent.item.consumable.ItemUseAnimation": { k: "enum", s: [], f: [], c: ["EAT", "DRINK"], m: [] },
  "io.papermc.paper.datacomponent.item.consumable.ConsumableTypesBootstrap": { k: "interface", s: [], f: [], c: [], m: [] },
};
const idx = (() => {
  const m = new Map<string, string[]>();
  for (const f of Object.keys(REC)) { const s = f.slice(f.lastIndexOf(".") + 1); m.set(s, [...(m.get(s) ?? []), f]); }
  return m;
})();
const deps = { classIndex: () => idx, getClass: (_v: string, f: string) => (REC as any)[f] ?? null, packageClasses: (_v: string, p: string) => Object.keys(REC).filter((f) => f.slice(0, f.lastIndexOf(".")) === p) };
const wsWith = (rel: string, text: string) => { const d = tmp(); fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), text); return d; };
const javac = (n: string) => fs.readFileSync(path.join(FX, "javac", `${n}.txt`), "utf8");

describe("memberindex: did-you-mean from the real member index", () => {
  it("parses javap output of enums, interfaces and generic methods", () => {
    const p = MI.parseJavap(`Compiled from "Material.java"\npublic final class org.bukkit.Material extends java.lang.Enum<org.bukkit.Material> implements org.bukkit.Keyed {\n  public static final org.bukkit.Material AIR;\n  public static final org.bukkit.Material NETHERITE_UPGRADE_SMITHING_TEMPLATE;\n  public static org.bukkit.Material[] values();\n  public boolean isBlock();\n  public <T extends org.bukkit.A<T>> java.util.List<T> foo(java.lang.Class<T>, int) throws java.io.IOException;\n}`);
    assert.equal(p.fqn, "org.bukkit.Material");
    assert.deepEqual(p.rec.c, ["AIR", "NETHERITE_UPGRADE_SMITHING_TEMPLATE"]);
    assert.deepEqual(p.rec.s, ["org.bukkit.Keyed"]);
    assert.deepEqual(p.rec.m.map((m: any) => m[0]), ["values", "isBlock", "foo"]);
    assert.equal(p.rec.m[2][1], 2);
  });
  it("picks only when the real jar has one close answer", () => {
    const pool = REC["org.bukkit.Material"].c;
    assert.equal(MI.pick("GOLD_HELMET", pool).name, "GOLDEN_HELMET");
    assert.equal(MI.pick("SMITHING_TEMPLATE", pool), null, "four templates contain both words: ambiguous");
    assert.equal(MI.pick("NETHERITE_UPGRADE_SMITHING_TEMPLATE", pool), null, "exists: nothing to fix");
    assert.equal(MI.pick("ZZZ_UNRELATED", pool), null);
    assert.equal(MI.pick("DIAMOND_HELMET", pool), null, "two helmets within reach: not unambiguous");
  });

  it("honey-bread: an import of ConsumableEffect becomes ConsumeEffect (the one close name in that package), every use renamed", () => {
    const rel = "src/main/java/dev/nxeon/plugins/honeybread/HoneyBread.java";
    const src = `package dev.nxeon.plugins.honeybread;\n\nimport java.util.List;\nimport org.bukkit.plugin.java.JavaPlugin;\n// ConsumableEffect in a comment is still renamed only as a token\nimport io.papermc.paper.datacomponent.item.consumable.ConsumableEffect;\n\npublic class HoneyBread extends JavaPlugin {\n  void f() {\n    List<ConsumableEffect> effects = List.of();\n    String s = "ConsumableEffect stays in a string";\n  }\n}\n`;
    // the recorded javac line numbers are for the real file; this one is shifted by the comment, so use matching ones
    const out = javac("honey-bread-consumable-effect").replace(":7:", ":6:").replace(":33:", ":10:");
    const d = wsWith(rel, src);
    const r = MI.fixMembers(out, d, "1.21.11", deps);
    assert.equal(r.fixes.length, 1);
    assert.equal(r.fixes[0].kind, "did-you-mean-class");
    const t = fs.readFileSync(path.join(d, rel), "utf8");
    assert.match(t, /import io\.papermc\.paper\.datacomponent\.item\.consumable\.ConsumeEffect;/);
    assert.match(t, /List<ConsumeEffect> effects/);
    assert.match(t, /"ConsumableEffect stays in a string"/);
  });
  it("armor-set: Material.SMITHING_TEMPLATE is ambiguous: no rewrite, the repair prompt gets only the relevant constants", () => {
    const rel = "src/main/java/dev/nxeon/plugins/armorset/ArmorSetPlugin.java";
    const lines = Array(40).fill("");
    lines.push("            ItemStack template = new ItemStack(Material.SMITHING_TEMPLATE);");
    const src = lines.join("\n");
    const d = wsWith(rel, src);
    const r = MI.fixMembers(javac("armor-set-smithing-template"), d, "1.21.11", deps);
    assert.deepEqual(r.fixes, []);
    assert.equal(fs.readFileSync(path.join(d, rel), "utf8"), src);
    const h = MI.hint("1.21.11", "org.bukkit.Material", "variable", "SMITHING_TEMPLATE", null, { getClass: deps.getClass });
    assert.match(h, /NETHERITE_UPGRADE_SMITHING_TEMPLATE/);
    assert.doesNotMatch(h, /HONEY_BOTTLE|BREAD\b/, "unrelated constants are not listed");
    const old = `- Material has no SMITHING_TEMPLATE in Paper 1.21.11. It has: ${REC["org.bukkit.Material"].c.join(", ")}.`;
    assert.ok(h.length <= old.length + 120);
  });
  it("a method typo on a Player resolves through the supertypes, at the caret column", () => {
    const rel = "src/main/java/dev/nxeon/plugins/demo/Demo.java";
    const lines = Array(11).fill("");
    lines.push('        player.sendActionbar(Component.text("hi")); // sendActionbar here is untouched');
    const d = wsWith(rel, lines.join("\n"));
    const r = MI.fixMembers(javac("method-typo"), d, "1.21.11", { ...deps, classIndex: () => new Map([["Player", ["org.bukkit.entity.Player"]]]) });
    assert.equal(r.fixes.length, 1);
    assert.equal(r.fixes[0].to, "Player.sendActionBar");
    const t = fs.readFileSync(path.join(d, rel), "utf8");
    assert.match(t, /player\.sendActionBar\(Component\.text\("hi"\)\); \/\/ sendActionbar here is untouched/);
  });
  it("a shifted line (an import was inserted earlier in the round) is not edited blindly", () => {
    const rel = "src/main/java/dev/nxeon/plugins/demo/Demo.java";
    const d = wsWith(rel, `import x.Y;\n${Array(11).fill("").join("\n")}\nSOMETHING ELSE\n`);
    const r = MI.fixMembers(javac("method-typo"), d, "1.21.11", { ...deps, classIndex: () => new Map([["Player", ["org.bukkit.entity.Player"]]]) });
    assert.deepEqual(r.fixes, []);
  });
  it("List<TextComponent> toList stays the job of fixListSubtype (recorded javac output)", () => {
    const rel = "src/main/java/dev/nxeon/plugins/demo/Demo.java";
    const lines = Array(19).fill("");
    lines.push("                .toList();");
    const d = wsWith(rel, lines.join("\n"));
    assert.equal(MI.fixMembers(javac("to-list-text-component"), d, "1.21.11", deps).fixes.length, 0);
    assert.equal(AF.fixListSubtype(javac("to-list-text-component"), d).fixes.length, 1);
  });
  it("fixCompile only runs the member index with MB_MEMBER_INDEX=1 (default off)", () => {
    assert.equal(MI.enabled({}), false);
    assert.equal(MI.enabled({ MB_MEMBER_INDEX: "1" }), true);
    const src = fs.readFileSync(path.join(MB, "autofix.js"), "utf8");
    assert.match(src, /if \(MI\.enabled\(\)\)/);
  });
  it("apiHints uses the ranked relevant members when the flag is on, the old list when off", () => {
    const rel = "src/main/java/dev/nxeon/plugins/armorset/ArmorSetPlugin.java";
    const d = wsWith(rel, `import org.bukkit.Material;\nclass A { void f() { Material.SMITHING_TEMPLATE.name(); } }\n`);
    const out = javac("armor-set-smithing-template").replace(":41:", ":2:");
    const prev = process.env.MB_MEMBER_INDEX;
    try {
      delete process.env.MB_MEMBER_INDEX;
      const off = PC.apiHints(out, d, "9.9.9"); // no jar, no index: nothing to say (unchanged behaviour)
      assert.equal(off, "");
    } finally { if (prev !== undefined) process.env.MB_MEMBER_INDEX = prev; }
  });
});

// ----------------------------------------------------------------------------------------------- workspace map
const goldenWs = (name: string) => {
  const g = path.join(MB, "golden", "plugins", name);
  const d = tmp();
  fs.mkdirSync(path.join(d, "src/main/resources"), { recursive: true });
  fs.cpSync(path.join(g, "src"), path.join(d, "src/main/java"), { recursive: true });
  fs.copyFileSync(path.join(g, "plugin.yml"), path.join(d, "src/main/resources/plugin.yml"));
  return d;
};

describe("workspace map for change builds", () => {
  const real = fs.existsSync(path.join(MB, "golden", "plugins", "mc-crates", "plugin.yml"));
  it("maps a real plugin: commands, permissions, events, signatures, no bodies", { skip: !real }, () => {
    const d = goldenWs("mc-crates");
    const m = WM.build(d, {});
    assert.ok(m && m.files === 1);
    assert.match(m.text, /^WORKSPACE MAP/);
    assert.match(m.text, /commands: \/crate/);
    assert.match(m.text, /permissions: goldencrates\.use, goldencrates\.admin/);
    assert.match(m.text, /events: PlayerInteractEvent/);
    assert.match(m.text, /onCommand\(CommandSender sender, Command command, String label, String\[\] args\): boolean/);
    assert.doesNotMatch(m.text, /return |dropItemNaturally/);
  });
  it("is much smaller than the source it replaces, and deterministic", { skip: !real }, () => {
    const d = goldenWs("mc-crates");
    const raw = fs.readdirSync(path.join(d, "src/main/java/dev/nxeon/golden/crates")).map((f) => fs.statSync(path.join(d, "src/main/java/dev/nxeon/golden/crates", f)).size).reduce((a, b) => a + b, 0);
    const a = WM.build(d, {});
    assert.ok(a.tokens * 3 < Math.ceil(raw / 3.6), `${a.tokens} vs ${Math.ceil(raw / 3.6)}`);
    assert.equal(WM.build(d, {}).text, a.text);
  });
  it("honours the token cap by dropping detail level by level, then truncates with a note", { skip: !real }, () => {
    const d = goldenWs("mc-crates");
    const full = WM.build(d, { maxTokens: 5000 });
    const small = WM.build(d, { maxTokens: 260 });
    assert.ok(small.level > full.level);
    assert.ok(small.tokens <= 260);
    const tiny = WM.build(d, { maxTokens: 201 });
    assert.ok(tiny.tokens <= 202);
  });
  it("change prompts: byte-identical without a map, the map block and no 'list the directory' with one", () => {
    const rec = { prompt: "a spawn plugin", changeRequest: "add /warp", mcVersion: "1.21.11", assets: null };
    const plain = P.changePrompt(rec, "/work/x", []);
    assert.equal(P.changePrompt({ ...rec, workspaceMap: "" }, "/work/x", []), plain);
    assert.match(plain, /Read the existing files you need first \(all in one response\)/);
    const withMap = P.changePrompt({ ...rec, workspaceMap: "WORKSPACE MAP\nX" }, "/work/x", []);
    assert.match(withMap, /<workspace-map>\nWORKSPACE MAP\nX\n<\/workspace-map>\n<request>\nadd \/warp/);
    assert.match(withMap, /do not list or search the directory/);
    const imp = { changeRequest: "x", mcVersion: "1.21.11", assets: null, imported: null };
    assert.equal(P.importChangePrompt({ ...imp, workspaceMap: "" }, "/w", [], 0), P.importChangePrompt(imp, "/w", [], 0));
    assert.match(P.importChangePrompt({ ...imp, workspaceMap: "M" }, "/w", [], 0), /<workspace-map>\nM\n<\/workspace-map>/);
  });
  it("is off by default and recorded on the build when on (server.js wiring)", () => {
    assert.equal(WM.enabled({}), false);
    assert.equal(WM.enabled({ MB_WORKSPACE_MAP: "1" }), true);
    const s = fs.readFileSync(path.join(MB, "server.js"), "utf8");
    assert.match(s, /if \(rec\.baseBuildId && WM\.enabled\(\)\)/);
    assert.match(s, /rec\.workspaceMap = \{ tokens: wm\.tokens/);
  });
});

