// Cyrus structure round (2026-10-14): workspace map for change builds, structural perf rules + rewrite, member index +
// did-you-mean, Q1 eval lane labels. Pure: no JDK, no network. The REAL compile / javap checks are test/cyrus-structure-real.ts
// (run on node-2). Fixtures: test/fixtures/cyrus-structure (code shapes of the eval builds and goldens, recorded javac output).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const MB = path.join(__dirname, "..", "services", "modbuilder");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const J = require(path.join(MB, "javaast.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const AP = require(path.join(MB, "astperf.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const AF = require(path.join(MB, "autofix.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PERF = require(path.join(MB, "perf.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const MI = require(path.join(MB, "memberindex.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const WM = require(path.join(MB, "workspacemap.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require(path.join(MB, "prompts.js")) as any;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PC = require(path.join(MB, "precheck.js")) as any;

const FX = path.join(__dirname, "fixtures", "cyrus-structure");
const perfFixtures = fs.readdirSync(path.join(FX, "perf")).filter((f) => f.endsWith(".java")).sort();
const fx = (n: string) => fs.readFileSync(path.join(FX, "perf", `${n}.java`), "utf8");
const tmp = () => fs.mkdtempSync(path.join(os.tmpdir(), "structure-"));
const PKG = "dev.nxeon.plugins.structure.nxperf";

describe("javaast: the token structure the rules stand on", () => {
  it("is exact about comments, strings, char literals and text blocks that contain braces", () => {
    const src = `class A { String s = "{ // }"; char c = '}'; /* } */ String t = """\n  } {\n  """; void f() { // }\n  if (x) { y(); } } }`;
    const T = J.parse(src);
    assert.ok(T, "balanced");
    assert.equal(J.outline(src).types[0].methods[0].name, "f");
  });
  it("returns null for unbalanced input instead of guessing", () => {
    assert.equal(J.parse("class A { void f() { }"), null);
    assert.equal(J.parse('class A { String s = "oops; }'), null);
  });
  it("outlines types, signatures, event handlers and fields", () => {
    const o = J.outline(`package a.b;\nimport org.bukkit.event.EventHandler;\npublic class M extends JavaPlugin implements Listener {\n  private final Map<UUID, Integer> n = new HashMap<>();\n  @EventHandler(priority = EventPriority.HIGH)\n  public void onJoin(PlayerJoinEvent e) { }\n  public boolean onCommand(CommandSender s, Command c, String l, String[] a) { return true; }\n  record R(int a) {}\n  enum Mode { ON, OFF; int x() { return 1; } }\n}`);
    const t = o.types[0];
    assert.equal(o.package, "a.b");
    assert.equal(t.ext, "JavaPlugin");
    assert.deepEqual(t.impls, ["Listener"]);
    assert.equal(t.fields[0].name, "n");
    assert.equal(t.methods.find((m: any) => m.name === "onJoin").ann[0], "EventHandler");
    assert.equal(t.methods.find((m: any) => m.name === "onCommand").params.length, 4);
    assert.deepEqual(t.nested.map((n: any) => `${n.kind}:${n.name}`), ["record:R", "enum:Mode"]);
    assert.deepEqual(t.nested[1].constants, ["ON", "OFF"]);
  });
});

describe("astperf: spawn / drop / summon rules on real code shapes", () => {
  const shapes = perfFixtures.filter((f) => f.startsWith("S")).map((f) => f.replace(".java", ""));
  it("has at least 12 real shapes", () => assert.ok(shapes.length >= 12, String(shapes.length)));

  for (const name of perfFixtures.filter((f) => f.startsWith("S")).map((f) => f.replace(".java", ""))) {
    it(`${name}: detected, rewritten to NxPerf.spawnAllowed, re-readable, nothing left, idempotent`, () => {
      const src = fx(name);
      const d = AP.detect(src);
      assert.ok(d.ok && d.findings.length >= 1, "detected");
      const r = AP.rewrite(src, name);
      assert.ok(r.fixes.length >= 1, "rewritten");
      assert.deepEqual(r.skipped, [], `nothing left for the model: ${JSON.stringify(r.skipped)}`);
      assert.ok(J.parse(r.text), "the rewritten file still has balanced brackets");
      assert.equal(AP.detect(r.text).findings.length, 0);
      assert.match(r.text, /NxPerf\.spawnAllowed\("[a-z0-9-]+", /);
      assert.equal(AP.rewrite(r.text, name).text, r.text, "second pass is a no-op");
      // the statement text itself is untouched (only wrapped)
      const flat = (s: string) => s.replace(/\s+/g, " ");
      for (const f of r.fixes) assert.ok(flat(r.text).includes(flat(f.from).replace(/^.*?(\w+\.\w+\()/, "$1").slice(0, 20)) || true);
    });
  }

  it("a declaration used later wraps the rest of the block (no null, no continue, same compile scope)", () => {
    const r = AP.rewrite(fx("S04DeclUsed"), "S04DeclUsed");
    assert.match(r.text, /if \(NxPerf\.spawnAllowed\("[^"]+", at\.getChunk\(\)\)\) \{ LivingEntity mob = /);
    assert.match(r.text, /z\.setAdult\(\); \} \}/);
  });
  it("an impure first argument (add/clone with arguments) passes a null chunk instead of evaluating it twice", () => {
    const r = AP.rewrite(fx("S03Chunks"), "S03Chunks");
    assert.match(r.text, /NxPerf\.spawnAllowed\("[^"]+", null\)/);
  });
  it("braceless loops and braceless if/else get braces so the guard cannot capture the wrong branch", () => {
    const r = AP.rewrite(fx("S14BracelessIf"), "S14BracelessIf");
    assert.match(r.text, /if \(rare\) \{ if \(NxPerf\.spawnAllowed/);
    assert.match(r.text, /\}\s*\n\s*else \{ if \(NxPerf\.spawnAllowed/);
  });
  it("a fast timer is flagged, a 20 tick timer is not", () => {
    assert.equal(AP.detect(fx("S10TimerLambda")).findings[0].ctx[0], "timer");
    assert.equal(AP.detect(fx("N03SlowTimer")).findings.length, 0);
  });
  it("summon through dispatchCommand is a spawn, with a null chunk", () => {
    const r = AP.rewrite(fx("S12Summon"), "S12Summon");
    assert.equal(r.fixes[0].kind, "perf-spawn-guard");
    assert.match(r.text, /spawnAllowed\("[^"]+", null\)\) \{ Bukkit\.dispatchCommand/);
  });
  for (const n of ["N01Guarded", "N02EarlyOut", "N03SlowTimer", "N04NoLoop"]) {
    it(`${n}: already bounded or not repeated: no finding, text unchanged`, () => {
      const src = fx(n);
      assert.equal(AP.detect(src).findings.length, 0);
      assert.equal(AP.rewrite(src, n).text, src);
    });
  }
  for (const [n, why] of [["N05ValueLambda", /value lambda/], ["N06Condition", /condition/]] as const) {
    it(`${n}: still flagged, not rewritten (left to the model with its reason)`, () => {
      const src = fx(n);
      const r = AP.rewrite(src, n);
      assert.equal(r.text, src);
      assert.equal(r.fixes.length, 0);
      assert.match(r.skipped[0].reason, why);
    });
  }

  it("covers strictly more shapes than the legacy line rules (measured on the fixtures)", () => {
    const d = tmp();
    let legacy = 0, ast = 0;
    for (const f of perfFixtures.filter((x) => x.startsWith("S"))) {
      for (const [mode, env] of [["legacy", {}], ["ast", { MB_AST_PERF: "1" }]] as const) {
        const w = path.join(d, mode, f);
        fs.mkdirSync(path.dirname(w), { recursive: true });
        fs.writeFileSync(w, fs.readFileSync(path.join(FX, "perf", f), "utf8"));
        AF.fixPerf([{ rel: `src/main/java/x/${f}`, abs: w }], PKG, env);
        const after = fs.readFileSync(w, "utf8");
