// ---------------------------------------------------------------------------------------------- member index
const REC = {
  "org.bukkit.Material": { k: "class", s: [], f: [], c: ["AIR", "DIAMOND", "GOLDEN_HELMET", "IRON_HELMET", "NETHERITE_UPGRADE_SMITHING_TEMPLATE", "COAST_ARMOR_TRIM_SMITHING_TEMPLATE", "SENTRY_ARMOR_TRIM_SMITHING_TEMPLATE", "DUNE_ARMOR_TRIM_SMITHING_TEMPLATE", "HONEY_BOTTLE", "BREAD"], m: [["isBlock", 0, "boolean", ""]] },
  "org.bukkit.entity.Player": { k: "interface", s: ["org.bukkit.entity.HumanEntity"], f: [], c: [], m: [["sendActionBar", 1, "void", "Component"], ["sendMessage", 1, "void", "String"], ["kickPlayer", 1, "void", "String"]] },
  "org.bukkit.entity.HumanEntity": { k: "interface", s: ["org.bukkit.entity.LivingEntity"], f: [], c: [], m: [["getInventory", 0, "PlayerInventory", ""], ["openInventory", 1, "InventoryView", "Inventory"]] },
  "org.bukkit.entity.LivingEntity": { k: "interface", s: [], f: [], c: [], m: [["getHealth", 0, "double", ""], ["setHealth", 1, "void", "double"], ["setAI", 1, "void", "boolean"]] },
  "io.papermc.paper.datacomponent.item.consumable.ConsumeEffect": { k: "interface", s: [], f: [], c: [], m: [["applyStatusEffects", 2, "ConsumeEffect", "List,float"]] },
  "io.papermc.paper.datacomponent.item.consumable.ItemUseAnimation": { k: "enum", s: [], f: [], c: ["EAT", "DRINK"], m: [] },
  "io.papermc.paper.datacomponent.item.consumable.ConsumableTypesBootstrap": { k: "interface", s: [], f: [], c: [], m: [] },
};
const idx = (() => {
  const m = new Map<string, string[]>();
  for (const f of Object.keys(REC)) { const s = f.slice(f.lastIndexOf(".") + 1); m.set(s, [...(m.get(s) ?? []), f]); }
  return m;
})();
const deps = { classIndex: () => idx, getClass: (_v: string, f: string) => (REC as any)[f] ?? null, packageClasses: (_v: string, p: string) => Object.keys(REC).filter((f) => f.slice(0, f.lastIndexOf(".")) === p) };
const wsWith = (rel: string, text: string) => { const d = tmp(); fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), text); return d; };
const javac = (n: string) => fs.readFileSync(path.join(FX, "javac", `${n}.txt`), "utf8");

describe("memberindex: did-you-mean from the real member index", () => {
  it("parses javap output of enums, interfaces and generic methods", () => {
    const p = MI.parseJavap(`Compiled from "Material.java"\npublic final class org.bukkit.Material extends java.lang.Enum<org.bukkit.Material> implements org.bukkit.Keyed {\n  public static final org.bukkit.Material AIR;\n  public static final org.bukkit.Material NETHERITE_UPGRADE_SMITHING_TEMPLATE;\n  public static org.bukkit.Material[] values();\n  public boolean isBlock();\n  public <T extends org.bukkit.A<T>> java.util.List<T> foo(java.lang.Class<T>, int) throws java.io.IOException;\n}`);
    assert.equal(p.fqn, "org.bukkit.Material");
    assert.deepEqual(p.rec.c, ["AIR", "NETHERITE_UPGRADE_SMITHING_TEMPLATE"]);
    assert.deepEqual(p.rec.s, ["org.bukkit.Keyed"]);
    assert.deepEqual(p.rec.m.map((m: any) => m[0]), ["values", "isBlock", "foo"]);
    assert.equal(p.rec.m[2][1], 2);
  });
  it("picks only when the real jar has one close answer", () => {
    const pool = REC["org.bukkit.Material"].c;
    assert.equal(MI.pick("GOLD_HELMET", pool).name, "GOLDEN_HELMET");
    assert.equal(MI.pick("SMITHING_TEMPLATE", pool), null, "four templates contain both words: ambiguous");
    assert.equal(MI.pick("NETHERITE_UPGRADE_SMITHING_TEMPLATE", pool), null, "exists: nothing to fix");
    assert.equal(MI.pick("ZZZ_UNRELATED", pool), null);
    assert.equal(MI.pick("DIAMOND_HELMET", pool), null, "two helmets within reach: not unambiguous");
  });

  it("honey-bread: an import of ConsumableEffect becomes ConsumeEffect (the one close name in that package), every use renamed", () => {
    const rel = "src/main/java/dev/nxeon/plugins/honeybread/HoneyBread.java";
    const src = `package dev.nxeon.plugins.honeybread;\n\nimport java.util.List;\nimport org.bukkit.plugin.java.JavaPlugin;\n// ConsumableEffect in a comment is still renamed only as a token\nimport io.papermc.paper.datacomponent.item.consumable.ConsumableEffect;\n\npublic class HoneyBread extends JavaPlugin {\n  void f() {\n    List<ConsumableEffect> effects = List.of();\n    String s = "ConsumableEffect stays in a string";\n  }\n}\n`;
    // the recorded javac line numbers are for the real file; this one is shifted by the comment, so use matching ones
    const out = javac("honey-bread-consumable-effect").replace(":7:", ":6:").replace(":33:", ":10:");
    const d = wsWith(rel, src);
    const r = MI.fixMembers(out, d, "1.21.11", deps);
    assert.equal(r.fixes.length, 1);
    assert.equal(r.fixes[0].kind, "did-you-mean-class");
    const t = fs.readFileSync(path.join(d, rel), "utf8");
    assert.match(t, /import io\.papermc\.paper\.datacomponent\.item\.consumable\.ConsumeEffect;/);
    assert.match(t, /List<ConsumeEffect> effects/);
