describe("Q1: eval lane labels for the four prompts the rc11 policy builds as ordinary plugins", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { loadEvalSet, laneOf } = require("../lib/cyrus/eval/set") as any;
  const set = loadEvalSet() as any[];
  for (const key of ["cov-tablist", "cov-warps", "cov-playtime-rewards", "cov-bossbar-titles"]) {
    it(`${key}: plain lane, no expected design lane, no asset stage, reason recorded`, () => {
      const p = set.find((x) => x.key === key);
      assert.ok(p, key);
      assert.equal(laneOf(p), "plain");
      assert.deepEqual(p.expectLanes, []);
      assert.ok(!p.designer);
      assert.match(p.laneNote, /rc11/);
    });
  }
  it("other designer-capable coverage prompts keep their designer lane", () => {
    for (const key of ["cov-quests", "cov-bosses", "cov-menus-gui"]) assert.equal(laneOf(set.find((x) => x.key === key)), "designer", key);
  });
});

